/* ---- debt service coverage. CFADS here is EBITDA less tax: this model carries no working
   capital, no maintenance capex and no reserve account, so nothing else sits between the two.
   Restricted to full operating years that are also amortising years, so the partial first and
   last years and the post-tenor years (where debt service is zero) never enter the statistics. ---- */
function dscrSeries(rows,from,to){
 return rows.filter(r=>r.y>=from&&r.y<to&&(r.int+r.repay)>1e-9)
            .map(r=>({y:r.y,v:(r.ebitda-(r.tax||0))/(r.int+r.repay)}));
}
function dscrStats(s){
 if(!s.length)return null;
 const v=s.map(x=>x.v);
 return {min:Math.min(...v),max:Math.max(...v),avg:v.reduce((a,b)=>a+b,0)/v.length,
         n:v.length,minY:s[v.indexOf(Math.min(...v))].y,from:s[0].y,to:s[s.length-1].y};
}
function dscrBadge(st){
 if(!st)return '';
 const c=st.min>=1.3?'#43c079':st.min>=1.15?'#ffb23e':'#ff6b6b';
 return `<span style="color:${c}">min ${fmt(st.min,2)}x</span> · avg ${fmt(st.avg,2)}x · max ${fmt(st.max,2)}x`;
}

