/* ---- The spread the battery needs, not the cost of what it sells ----------------------------
   LCOS divides total cost by delivered energy and hands back a number that includes the price of
   the electricity the battery bought. That makes it useless for a go/no-go: a battery selling at
   200 and buying at 199 has a great LCOS and no business. The break-even condition is on the gap.

     required spread = fixed cost per MWh delivered + buy price x (1/RTE - 1)

   Term one is the asset: capex annuity plus opex, divided by the megawatt-hours it actually
   delivers. Term two is the round-trip loss priced at what the lost energy cost to buy. Achieved
   spread is the backtest: charge the cheapest hours of each day, discharge the priciest, on the
   real Austrian curve. Sell-side volumes only, so it compares like for like with the requirement.
---------------------------------------------------------------------------------------------- */

function spreadDur(){let best=8;for(const h of [2,4,6,8])if(Math.abs(h-M.battery.durationH)<Math.abs(best-M.battery.durationH))best=h;return best;}

/* The live calculator. Same algebra as the backtest, wired to the sliders, and it reconciles with
   the table underneath because both take their throughput and their prices from the optimiser
   rather than from a rounded cycle count. */
function spreadRow(){
 const b=M.battery, hs=[2,4,6,8];
 let best=SPREAD.byDur[SPREAD.byDur.length-1];
 for(const r of SPREAD.byDur) if(Math.abs(r.h-b.durationH)<Math.abs(best.h-b.durationH)) best=r;
 return best;
}
function spreadCalc(){
 const b=M.battery, mac=M.macro, row=spreadRow(), L=row.last;
 const rate=mac.allInRate, life=b.lifeY||25;
 const cell=b.powerMW*b.durationH*1000*b.capexPerKWh/1e6;
 const capex=cell+(b.substation||0)+(b.interconnect||0);
 const opex=cell*(b.opexPct||0.02);
 const crf=rate/(1-Math.pow(1+rate,-life));
 const F=capex*crf+opex;                                   // €m a year of fixed charge
 // throughput scales with the tradeable depth and the power, both of which the sliders move
 const scale=(b.powerMW/500)*((b.durationH*(1-(b.socFloor||0)))/(row.h*0.9));
 const sold=L.soldGWh*1000*scale;                          // MWh sold in a year
 const fixed=sold>0?F*1e6/sold:0;
 const buy=L.buy, sell=L.sell;
 const loss=buy*(1/b.rte-1);
 const req=fixed+loss, ach=sell-buy;
 return{capex,cell,opex,F,crf,rate,life,sold,fixed,buy,sell,loss,req,ach,margin:ach-req,row,L,
   grossM:(sell-buy)*sold/1e6, netM:(sell-buy)*sold/1e6-F};
}

function spreadPanel(){
 const b=M.battery, C=spreadCalc();
 const Y=SPREAD.byDurYear[String(spreadDur())]||SPREAD.byDurYear['8'];
 const ok=C.margin>0, col=ok?'var(--nx-green-hi)':'#ff6b6b';
 const clear=Y.filter(r=>r.margin>0);
 setTimeout(drawSpreadCharts,0);
 const durSeg=`<div class="fRow" style="margin-bottom:12px"><span class="fLbl">Duration</span><div class="seg">`+
   [2,4,6,8].map(d=>`<button class="${Math.round(b.durationH)===d?'on':''}" onclick="M.battery.durationH=${d};render()">${d} h</button>`).join('')+
   `</div><span class="muted" style="font-size:12.5px">${fmt(b.powerMW,0)} MW · ${fmt(b.powerMW*b.durationH/1000,1)} GWh · ${pct(b.socFloor||0,0)} held back for ride-through</span></div>`;
 return durSeg+`<div class="chart tall" id="sp_year"></div>
  <p class="muted" style="margin-top:10px">* 2026 runs to 10 August.</p>`;
}
