/* ---- print -------------------------------------------------------------------------------
   Print the page you are on, or walk every tab and print the lot as one document. Either way the
   surface goes to paper, the navigation goes away and panels are told not to split across a page
   break, which is what makes the difference between a printout and a document. ---- */
let PRINTALL=false;
async function printView(all){
 const wasTheme=THEME, wasTab=active;
 if(THEME!=='light')setTheme('light',true);
 document.body.classList.add('printing');
 if(all){
  PRINTALL=true;
  const host=document.getElementById('printAll'); host.innerHTML='';
  const tabs=TABS.map(t=>t[0]).filter(t=>!gateLocked(t));
  for(const t of tabs){
   active=t; render();
   await new Promise(r=>setTimeout(r,1500));
   const sec=document.createElement('section');
   sec.className='paPage';
   sec.innerHTML='<div class="paTab">'+(TABS.find(x=>x[0]===t)||[])[1]+'</div>'+document.getElementById('main').innerHTML;
   // Plotly draws into divs; copy the rendered SVG across rather than an empty shell
   const from=document.querySelectorAll('#main .js-plotly-plot'), to=sec.querySelectorAll('.chart');
   host.appendChild(sec);
  }
  active=wasTab; render();
  await new Promise(r=>setTimeout(r,900));
  document.body.classList.add('printAllOn');
 }
 await new Promise(r=>setTimeout(r,650));
 window.print();
 setTimeout(()=>{
   document.body.classList.remove('printing','printAllOn');
   const host=document.getElementById('printAll'); if(host)host.innerHTML='';
   PRINTALL=false;
   if(wasTheme!=='light')setTheme(wasTheme); else render();
 },700);
}
