function scenOpenFile(inp){
 const f=inp.files&&inp.files[0]; if(!f)return;
 const r=new FileReader();
 r.onload=()=>{try{const j=JSON.parse(r.result); if(j&&j.model){restore(j.model);render();}else alert('That file does not carry a model.');}
   catch(e){alert('Could not read that file.');}};
 r.readAsText(f);
}
function scenLink(){
 try{
  const s=btoa(unescape(encodeURIComponent(JSON.stringify(snapshot()))));
  const url=location.origin+location.pathname+'#s='+s;
  if(navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(url).then(()=>toast('Link copied. It carries every slider position.'),()=>prompt('Copy this link',url));
  }else prompt('Copy this link',url);
 }catch(e){alert('Could not build a link from this state.');}
}
function scenFromHash(){
 try{
  const m=/[#&]s=([^&]+)/.exec(location.hash||''); if(!m)return false;
  const j=JSON.parse(decodeURIComponent(escape(atob(m[1]))));
  restore(j); return true;
 }catch(e){return false;}
}
