const SCORE=[['spvIRR','SPV equity IRR','pct'],['dc9','Margin needed for a 9% return','pctpt'],
 ['windIRR','Wind equity IRR','pct'],['solarIRR','Solar equity IRR','pct'],['battIRR','Battery equity IRR','pct'],
 ['windLCOE','Wind LCOE','eur'],['solarLCOE','Solar LCOE','eur'],['selfPct','Self-supply','pctpt'],
 ['genGWh','Generation','gwh'],['capex','SPV capex','eurm'],['equity','SPV equity','eurm']];
function sfmt(k,v){
 if(v==null||!isFinite(v))return 'n/a';
 const t=(SCORE.find(x=>x[0]===k)||[])[2];
 if(t==='pct')return fmt(v*100,1)+'%';
 if(t==='pctpt')return fmt(v,1)+'%';
 if(t==='eur')return '€'+fmt(v,1);
 if(t==='eurm')return '€'+fmt(v,0)+'m';
 if(t==='gwh')return fmt(v,0)+' GWh';
 return fmt(v,2);
}

/* ---- sensitivity --------------------------------------------------------------------------
   Move one input at a time across a range we would defend in a meeting, recompute the whole
   model, and record what the chosen output did. Nothing is approximated. ------------------- */
const LEVERS=[
 {k:'PPA price to the parks', path:['wind','ppa'], also:[['solar','ppa']], lo:70, hi:130, u:'€/MWh'},
 {k:'Wind capacity factor', path:['wind','grossCF'], lo:0.255, hi:0.32, u:''},
 {k:'Solar capacity factor', path:['solar','grossCF'], lo:0.125, hi:0.175, u:''},
 {k:'Wind capex', path:['wind','capexPerMW'], lo:1.15, hi:1.75, u:'€m/MW'},
 {k:'Solar capex', path:['solar','capexPerMW'], lo:0.45, hi:0.80, u:'€m/MW'},
 {k:'Battery capex', path:['battery','capexPerKWh'], lo:90, hi:190, u:'€/kWh'},
 {k:'All-in debt rate', path:['macro','allInRate'], lo:0.032, hi:0.068, u:''},
 {k:'Gearing', path:['macro','gearing'], lo:0.55, hi:0.80, u:''},
 {k:'Debt tenor', path:['macro','tenor'], lo:15, hi:25, u:'yr'},
 {k:'Merchant tail price', path:['macro','merchReal'], lo:70, hi:130, u:'€/MWh'},
 {k:'Private line cost', path:['conn','directPer100'], lo:7.54, hi:11.32, u:'€m/100MW'},   // written cable estimate vs spoken lump total, both on the export base
 {k:'NE3 capacity charge', path:['dc','gridCapFeeKW'], lo:30, hi:60, u:'€/kW/yr'},
 {k:'NE3 energy fee', path:['dc','gridEnergyFee'], lo:5, hi:14, u:'€/MWh'},
 {k:'BE Trading margin', path:['dc','beMargin'], lo:0.01, hi:0.06, u:''},
 {k:'SPV margin on energy', path:['dc','spvMargin'], lo:0.01, hi:0.08, u:''},
 {k:'Solar DC to AC ratio', path:['conn','dcac'], lo:1.05, hi:1.40, u:'x'},
 {k:'Battery grid access year', path:['battery','gridYear'], lo:2032, hi:2099, u:''},
 {k:'Tax rate', path:['macro','tax'], lo:0.18, hi:0.28, u:''},
 {k:'Inflation', path:['macro','infl'], lo:0.012, hi:0.032, u:''}
];
let tornOut='spvIRR', _TORN=null;
function setAt(m,path,v){m[path[0]][path[1]]=v;}
function runTornado(outKey){
 const base=snapshot(), b0=scoreCard()[outKey];
 const rows=[];
 for(const L of LEVERS){
  const vals=[];
  for(const v of [L.lo,L.hi]){
   restore(JSON.parse(JSON.stringify(base)));
   setAt(M,L.path,v); (L.also||[]).forEach(p=>setAt(M,p,v));
   _SUPC=null;_CLIPF=null;
   const s=scoreCard()[outKey];
   vals.push(isFinite(s)?s:null);
  }
  rows.push({k:L.k,u:L.u,lo:L.lo,hi:L.hi,vLo:vals[0],vHi:vals[1],
    swing:(vals[0]==null||vals[1]==null)?0:Math.abs(vals[1]-vals[0])});
 }
 restore(base); _SUPC=null;_CLIPF=null;
 rows.sort((a,b)=>b.swing-a.swing);
 return {base:b0,rows,out:outKey};
}
function tornado(){
 if(_TORN&&_TORN.out===tornOut&&_TORN.key===JSON.stringify(snapshot()))return _TORN.v;
 const key=JSON.stringify(snapshot());
 const v=runTornado(tornOut);
 _TORN={out:tornOut,key,v};
 return v;
}

/* ---- the questions people actually ask ---------------------------------------------------- */
const ASKS=[
 {q:'What if the market doubles? Who pays?',
  apply:()=>{M.dc.resFix=198;M.dc.spvMode='pass';}, go:['summary','fin'],
  say:'Source price doubled. In pass-through the data center pays it, and the SPV return barely moves.'},
 {q:'What if the parks want €110 instead of €100?',
  apply:()=>{M.wind.ppa=110;M.solar.ppa=110;}, go:['summary','fin'],
  say:'Both PPA prices to €110. Watch the price the data center has to pay for a 9% return.'},
 {q:'What if solar comes in where AFRY says, not where the meters say?',
  apply:()=>{M.solar.grossCF=1157/8760;}, go:['solar','fin'],
  say:'Solar capacity factor set to AFRY’s P50 of 1,157 kWh/kWp. The metered plant runs 27% below this.'},
 {q:'What if the battery never gets grid access?',
  apply:()=>{M.battery.gridYear=2099;}, go:['summary','batt'],
  say:'No merchant year. The battery earns the reliability charge only.'},
 {q:'What if debt costs 2 points more?',
  apply:()=>{M.macro.allInRate=Math.min(0.08,M.macro.allInRate+0.02);M.battery.debtRate=Math.min(0.09,(M.battery.debtRate||0.05)+0.02);},
  go:['summary','fin'], say:'All-in rate and the battery debt rate both up 200 basis points.'},
 {q:'What if the network charge doubles by the time we build?',
  apply:()=>{M.dc.gridCapFeeKW=85.68;}, go:['datacentre','fin'],
  say:'NE3 capacity charge to €85.68/kW/yr, which is where BE’s own tariff path puts it in the 2040s.'},
 {q:'What if the battery has to pay network charges when it trades?',
  apply:()=>{M.battery.mktCapFee=true;}, go:['summary','batt'],
  say:'The NE3 Leistungspreis applied to the battery from its first merchant year.'},
 {q:'What if the inverters are tighter than we assume?',
  apply:()=>{M.conn.dcac=1.35;M.conn.clip=true;}, go:['summary','supply'],
  say:'DC to AC ratio to 1.35. More clipping, less delivered energy, a smaller line.'},
 {q:'What does the data center pay if the SPV only needs 7%?',
  apply:()=>{if((M.dc.spvMode||'pass')==='pass')M.dc.spvMargin=Math.round(solveMarginFor(0.07)*10000)/10000;
             else M.dc.dcPrice=Math.round(solveDcFor(0.07)*10)/10;}, go:['summary','fin'],
  say:'Margin solved for a 7% SPV equity return. The euro per MWh follows from it.'},
 {q:'What if only the first 200 MW is priced at €100?',
  apply:()=>{TRANCHE.t1MW=200;TRANCHE.p1=100;TRANCHE.p2=80;}, go:['summary','fin'],
  say:'Tranche one at €100 on 200 MW, the rest at €80.'},
 {q:'What breaks it? Show me everything at once.',
  apply:()=>{}, go:['summary','sens'], say:'Every input moved across its own range, ranked by effect.'}
];
function ask(i){
 const a=ASKS[i]; if(!a)return;
 a.apply(); _SUPC=null;_CLIPF=null;_TORN=null;
 active=a.go[0];
 if(a.go[0]==='summary')spvView=a.go[1];
 else if(a.go[0]==='solar'||a.go[0]==='wind')assetView[a.go[0]]=a.go[1];
 else if(a.go[0]==='battery'){active='summary';spvView='batt';}
 else if(a.go[0]==='datacentre')dcView=a.go[1];
 buildNav(); render(); toast(a.say);
}

