/* ---- how concentrated is the battery's income --------------------------------------------
   Every figure here is the daily result of the same backtest that produces the spreads, sorted
   and cumulated. The Gini coefficient is on daily gross margin, so 0 would be the same money every
   day and 1 would be all of it on one day. --------------------------------------------------- */
let concDur='8', concYear='last12m';

/* ---- What the direct line costs, and why the number has moved twice -----------------------
   Three estimates, none of them the same measurement. The written estimate is a rate per 100 MW
   on a roughly 10 km, 30 kV reference with three ground variants. The spoken figure is a lump
   total for the real portfolio at 110 kV. Overhead has never been priced by anyone.

   Everything below is priced on export capacity, lineMW(), the same base the model bills the line
   on, because a cable is sized on what the plant can push down it. Solar enters at AC.
------------------------------------------------------------------------------------------- */
const BE_LUMP=69.9;          // €m, all parks, 110 kV, spoken figure
const LINEV=[
 {k:'vdr7',  r:7.54, lbl:'Cable plough, mixed ground',           src:'written estimate',  kv:'30 kV',  note:'cheapest of the three, needs soft open ground the whole way. Carried in the model.'},
 {k:'vdr7b', r:7.98, lbl:'Fields and tracks, no drilling',        src:'written estimate',  kv:'30 kV',  note:'open trench across farmland'},
 {k:'vdr7c', r:9.09, lbl:'Mixed ground, horizontal drilling',     src:'written estimate',  kv:'30 kV',  note:'where the route crosses roads, canals, rail and buried services'},
 {k:'be70',  r:null, lbl:'Burgenland Energie lump sum, all parks',src:'spoken figure',kv:'110 kV', note:'a total, not a rate, and their own engineers gave differing views on it.'}
];
/* Export capacity per project: wind as built, solar through the inverter ratio. */
function projAC(p){return p.t==='solar'?p.mw/(M.conn.dcac||1):p.mw;}
function projKm(p){return parseFloat(String(p.d).replace('~','').replace(',','.'));}
function lineACkm(){return PROJECTS.reduce((s,p)=>s+projAC(p)*projKm(p),0);}
/* What a given line rate does to the SPV, holding everything else. State is restored. */
function irrAtLine(rate){
 const keep=M.conn.directPer100; M.conn.directPer100=rate;
 const r=computeSPV(M.dc.dcPrice); const out={irr:r.irr,unit:r.unit};
 M.conn.directPer100=keep; return out;
}
function lineRows(){
 const mw=lineMW(), mwkm=lineACkm();
 return LINEV.map(v=>v.r==null
   ? {...v, flat:BE_LUMP, dist:BE_LUMP, eff:BE_LUMP/mw*100}
   : {...v, flat:mw*v.r/100, dist:mwkm*v.r/1000, eff:v.r});
}
function linePanel(){
 const mw=lineMW(), mwkm=lineACkm(), avg=mwkm/mw, cur=M.conn.directPer100;
 const rows=lineRows(), be=rows.find(r=>r.k==='be70'), drill=rows.find(r=>r.k==='vdr7c');
 const booked=mw*cur/100, nameplate=PROJECTS.reduce((s,p)=>s+p.mw,0);
 const longKm=PROJECTS.filter(p=>projKm(p)>=18);
 const wkm=PROJECTS.filter(p=>p.t==='wind').reduce((s,p)=>s+p.mw*projKm(p),0);
 const skm=PROJECTS.filter(p=>p.t==='solar').reduce((s,p)=>s+projAC(p)*projKm(p),0);
 const longShare=longKm.reduce((s,p)=>s+projAC(p)*projKm(p),0)/mwkm;
 const lo=irrAtLine(7.54), hi=irrAtLine(be.eff);
 setTimeout(drawLineChart,0);
 return `<div class="panel" style="margin-top:14px"><h3>The direct line, and why this number has moved twice</h3>
  <div class="kpis" style="margin-bottom:12px">
   ${kpi('Carried in the model','€'+fmt(cur,2),'m per 100 MW · €'+fmt(booked,0)+'m over '+fmt(mw,0)+' MW of export')}
   ${kpi('Route length, capacity weighted',fmt(avg,1),'km · the estimate assumes 10 km')}
   ${kpiM([['Written','€7.54','to €9.09 /100MW'],['Spoken','€'+fmt(BE_LUMP,0)+'m','€'+fmt(be.eff,2)+' /100MW'],['Overhead','n/a','never priced']],'#e8b13a')}
   ${kpi('Gap between the two','€'+fmt(BE_LUMP-booked,0),'m on the same '+fmt(mw,0)+' MW')}
  </div>
  <div class="chart" id="lineCmp"></div>
  <table style="margin-top:10px"><thead><tr><th>Basis</th><th>Source</th><th>Voltage</th><th>€m per 100 MW</th><th>At the 10 km reference</th><th>At the real route lengths</th><th></th></tr></thead><tbody>
  ${rows.map(r=>`<tr${Math.abs(cur-r.eff)<0.02?' style="background:rgba(0,154,68,.09)"':''}>
    <td><b>${r.lbl}</b><div class="muted" style="font-size:12.5px">${r.note}</div></td>
    <td>${r.src}</td><td>${r.kv}</td>
    <td><b>€${fmt(r.eff,2)}</b>${r.r==null?'<div class="muted" style="font-size:12.5px">implied</div>':''}</td>
    <td>${r.r==null?'<span class="muted">n/a, already a total</span>':'€'+fmt(r.flat,0)+'m'}</td>
    <td>${r.r==null?'<b>€'+fmt(r.dist,0)+'m</b>':'€'+fmt(r.dist,0)+'m'}</td>
    <td><button class="chip" style="cursor:pointer;padding:3px 9px;font-size:12.5px" onclick="M.conn.directPer100=${fmt2(r.eff)};M.conn.lineBasis='${r.k}';render()">use</button></td></tr>`).join('')}
  </tbody></table>
  <div class="info" style="margin-top:12px"><b>The two figures measure different things.</b> The written estimate is a rate per 100 MW on a reference route of about 10 km at 30 kV. Burgenland Energie's €${fmt(BE_LUMP,0)}m is a total for the real portfolio at 110 kV. Put on the same basis they nearly meet: the portfolio is ${fmt(mw,0)} MW of export capacity, the capacity-weighted route is ${fmt(avg,1)} km rather than 10, and the drilling variant at those distances gives <b>€${fmt(drill.dist,0)}m</b> against their <b>€${fmt(BE_LUMP,0)}m</b>, a ${fmt(Math.abs(BE_LUMP-drill.dist)/BE_LUMP*100,0)}% difference. What remains between them is the step from 30 kV to 110 kV, which has not been settled, and overhead construction, which neither side has priced. Overhead on the ${longKm.length} long rural routes would save roughly €${fmt(mwkm*7.54/1000*(1-1/1.6),0)}m to €${fmt(mwkm*7.54/1000*(1-1/3),0)}m if permitting allows it.
   <br><br><b>The model carries €7.54 because it is the only figure in writing.</b> The €${fmt(BE_LUMP,0)}m is a spoken figure and has not been confirmed in writing. The difference is worth about ${fmt((lo.irr-hi.irr)*10000,0)} basis points of SPV equity return (${fmt(lo.irr*100,2)}% against ${fmt(hi.irr*100,2)}%) and does not change what the data center pays, since the line sits in our capital and not in their bill. Each row in the table can be applied to the model with its button.
  </div>
 </div>`;
}
function fmt2(x){return Math.round(x*100)/100;}
function drawLineChart(){
 if(!document.getElementById('lineCmp'))return;
 const FAINT=TH().faint, rows=lineRows().filter(r=>r.r!=null);
 const lbl=rows.map(r=>r.lbl.split(',')[0]+'<br><span style="font-size:9px">'+r.kv+' · €'+fmt(r.r,2)+'/100 MW</span>');
 Plotly.react('lineCmp',[
  {x:lbl,y:rows.map(r=>r.flat),name:'At the 10 km reference route',type:'bar',
   marker:{color:'#39465a'},text:rows.map(r=>'€'+fmt(r.flat,0)+'m'),textposition:'outside',
   textfont:{size:12,color:'var(--t2)'},hovertemplate:'€%{y:.0f}m<extra>flat 10 km</extra>'},
  {x:lbl,y:rows.map(r=>r.dist),name:'At the real route lengths',type:'bar',
   marker:{color:'#46b45a'},text:rows.map(r=>'€'+fmt(r.dist,0)+'m'),textposition:'outside',
   textfont:{size:12,color:'var(--t2)'},hovertemplate:'€%{y:.0f}m<extra>real distances</extra>'}
 ],lay('What the private lines cost on each written variant',
   {barmode:'group',showlegend:true,margin:{t:76,b:78},xaxis:{gridcolor:FAINT},
    yaxis:{title:{text:'€m, all parks',font:{size:12}},gridcolor:FAINT,range:[0,BE_LUMP*1.32]},
    shapes:[{type:'line',xref:'paper',x0:0,x1:1,yref:'y',y0:BE_LUMP,y1:BE_LUMP,
             line:{color:'#e8b13a',width:1.6,dash:'dash'}}],
    annotations:[{xref:'paper',x:0.015,y:BE_LUMP,yref:'y',text:'Burgenland Energie lump sum €'+fmt(BE_LUMP,0)+'m at 110 kV',
             showarrow:false,yanchor:'bottom',xanchor:'left',font:{size:10,color:'#e8b13a'}}]}),CFG);
}
/* ---- Is the 1.20 DC to AC ratio an assumption or a measurement? -----------------------------
   Two tests on Burgenland Energie's own quarter-hourly meters. The first is peak export against
   nameplate, which gives an upper bound on the ratio. The second asks whether that peak is a
   ceiling the plant keeps hitting or simply the best quarter hour on record: a plant pinned at its
   inverter rating returns to the same number again and again, and one that is merely
   irradiance-limited does not. Wind is the control, because wind nameplate is already AC.
------------------------------------------------------------------------------------------- */

/* ---- The 500 MW wall ---------------------------------------------------------------------
   The data center takes 500 MW every hour. The fleet could in principle deliver 617.5 MW AC. This
   measures how often production actually exceeds what the data center can take, on the metered
   record at the model's scaling, and at larger fleets. One construction for every figure:
   co-metered window Jun 2024 to Jul 2026, shapes normalised to mean 1, scaled to the delivered
   capacity factors, capped at the AC ratings.
------------------------------------------------------------------------------------------- */

/* ---- Commercial terms, sealed ---------------------------------------------------------------
   The commercial terms are held encrypted, under their own code, separate from the data-room
   code. Locked, TERMS is null and every panel falls back to a neutral default that comes from our
   own record rather than from the document. Unlocked, the defaults move to the real numbers.
   Nothing sensitive exists in this file as plain text.
------------------------------------------------------------------------------------------- */

let TERMS=null;
async function termsDerive(pw){
 const km=await crypto.subtle.importKey('raw',new TextEncoder().encode(pw),'PBKDF2',false,['deriveKey']);
 return crypto.subtle.deriveKey({name:'PBKDF2',salt:new TextEncoder().encode('gdc-nickelsdorf::terms'),
   iterations:310000,hash:'SHA-256'},km,{name:'AES-GCM',length:256},false,['decrypt']);
}
async function termsTry(){
 const el=document.getElementById('tmPw'), msg=document.getElementById('tmMsg');
 const v=(el&&el.value)||''; if(!v){if(el)el.focus();return;}
 if(msg)msg.textContent='Opening…';
 try{
  const raw=Uint8Array.from(atob(TERMS_BLOB),c=>c.charCodeAt(0));
  if(String.fromCharCode(...raw.slice(0,4))!=='TRM1')throw new Error('header');
  const key=await termsDerive(v);
  const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:raw.slice(4,16)},key,raw.slice(16));
  TERMS=JSON.parse(new TextDecoder().decode(pt));
  try{sessionStorage.setItem('gdcTerms',v);}catch(e){}
  applyTerms(); render(); afterRender();
 }catch(e){ if(msg)msg.textContent='Not recognised.'; }
}
/* Move the sliders onto the real numbers. Only ever called after a successful decrypt. */
function applyTerms(){
 if(!TERMS)return;
 const t=TERMS;
 // Field names are opaque on purpose. Anyone reading this file learns that some numbers exist,
 // not what they are or what they describe.
 if(t.a!=null)M.site.leasePre=t.a;
 if(t.b!=null)M.site.leasePost=t.b;
 if(t.c!=null)M.site.partPct=t.c;
 if(t.d!=null)M.site.partCapM=t.d;
 if(t.e!=null)M.site.oneOff=t.e;
 if(t.f!=null)M.dc.revPerMW=t.f;
 if(t.i!=null)M.dc.claimShare=t.i;
 // Deliberately NOT applied to M.conn.wideInfra: opening the terms must not move the base case
 // underneath anyone. The figure is offered as a button on the perimeter panel instead.
 if(t.g!=null&&t.h!=null)TERMS._wide=t.g+t.h;
}
(async function termsBoot(){
 try{ const v=sessionStorage.getItem('gdcTerms'); if(!v)return;
   const raw=Uint8Array.from(atob(TERMS_BLOB),c=>c.charCodeAt(0));
   const key=await termsDerive(v);
   const pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:raw.slice(4,16)},key,raw.slice(16));
   TERMS=JSON.parse(new TextDecoder().decode(pt)); applyTerms();
   if(typeof render==='function'){render(); if(typeof afterRender==='function')afterRender();}
 }catch(e){}
})();
function termsBar(){
 return TERMS
  ? `<div class="info" style="margin-bottom:12px;padding:8px 12px"><b>Commercial terms open.</b> The lease, the participation fee, the infrastructure cost centres and the supply terms below are the ones in the executed drafts. <span class="muted">Held under a separate code, not exported, not in any BE-facing copy.</span></div>`
  : `<div class="warn" style="margin-bottom:12px;padding:8px 12px"><b>Commercial terms are sealed.</b> The land, participation and infrastructure figures below are neutral placeholders from our own record, not the negotiated terms. Everything still computes; only the starting values differ.
     <span style="display:inline-flex;gap:6px;align-items:center;margin-left:10px"><input type="password" id="tmPw" placeholder="terms code" style="width:130px;padding:3px 7px;font-size:12px" onkeydown="if(event.key==='Enter')termsTry()"><button class="chip" style="cursor:pointer" onclick="termsTry()">Open</button><span id="tmMsg" class="muted" style="font-size:12.5px"></span></span></div>`;
}
/* ============================================================================================
   THE THREE BUCKETS
   Three balance sheets sit behind one data center and the deal only works if all three clear. The
   power company sells the electricity and owns the lines and the battery. The data center buys the
   electricity, rents the ground and sells compute. The landowner rents the ground and takes a
   share of what the data center earns. Two of the three we can measure. The data center revenue we cannot,
   so it is an input, and the page says which anchors exist for it.
============================================================================================ */

/* ============================================================================================
   THE RENEWABLE SHARE
   A calculator, not an argument. Give it a claimed share and it returns the fleet that claim
   needs, on Burgenland Energie's own measured capacity factors. From 15 August 2027 the EU
   labelling regime publishes this number, so whichever one goes into a contract is the one that
   gets audited.
============================================================================================ */

/* ============================================================================================
   THE INFRASTRUCTURE PERIMETER, AND THE FIRM PRICE-OUT
   Two questions that move the return more than anything argued so far: how much of the data center
   electrical scope sits inside the power company, and whether it sells a fixed price on the
   ride-through leg.
============================================================================================ */

