/* The whole data-center universe on one page: what the power costs, what the build costs,
   and what each player carries. Power figures are this model, live; the shell and chip
   figures are 2026 market benchmarks per MW of critical IT load. */
function dcPage(){
 if(dcView!=='fin'&&dcView!=='tech')dcView='fin';
 const d=M.dc;
 const load=d.firmMW*8760;
 const head=pageHead('Data Center','','',dcSeg());
 if(dcView==='tech')return head+renderBlock('dcsite');

 // ---------- 1 · the power bill, read off the SPV model so both pages show one invoice ----------
 const W=computeAsset(M.wind), S=computeAsset(M.solar);
 const SPb=computeSPV(M.dc.dcPrice), y1b=SPb.rows.find(r=>r.y===FF)||{rev:0,bRev:0,gridCost:0,resPPA:0};
 const resGen=(M.wind.on!==false?(W.rows.find(r=>r.y===FF)||{prod:0}).prod:0)
             +(M.solar.on!==false?(S.rows.find(r=>r.y===FF)||{prod:0}).prod:0);
 const gridMWh=Math.max(0,load-resGen);
 const capFee=resCapFeeM(FF);
 const gridEnergy=Math.max(0,y1b.gridCost-capFee);
 const margin=Math.max(0,y1b.rev-y1b.resPPA-gridEnergy-capFee);
 const relFee=(computeBattery(M.battery).capRev||0);
 const total=y1b.rev+relFee;
 const unit=load>0?y1b.rev*1e6/load:0;
 const rows=[
  ['From the parks, under the PPA',resGen,resGen>0?y1b.resPPA*1e6/resGen:0,y1b.resPPA,'var(--nx-green-hi)'],
  ['From the grid, energy',gridMWh,gridMWh>0?gridEnergy*1e6/gridMWh:0,gridEnergy,'#93a49a'],
  ['Network capacity charge',null,null,capFee,'#ff6b6b'],
  ['SPV margin',null,null,margin,'#4aa8ff'],
  ['Battery reliability charge',null,null,relFee,'#b98cff']];
 const bar=(()=>{const W2=1100,tot=total||1;let x=0;
  const segs=rows.map(r=>{const w=r[3]/tot*W2;
    const seg=`<rect x="${x.toFixed(1)}" y="6" width="${Math.max(0,w-2).toFixed(1)}" height="36" rx="4" fill="${r[4]}" opacity=".85"/>`+
      (w>70?`<text x="${(x+w/2).toFixed(1)}" y="29" text-anchor="middle" font-size="14" font-weight="700" fill="#0b1410" font-family="Inter,sans-serif">€${fmt(r[3],0)}m</text>`:'');
    x+=w; return seg;}).join('');
  const leg=rows.map(r=>`<span style="white-space:nowrap"><i style="display:inline-block;width:11px;height:11px;border-radius:3px;background:${r[4]};margin-right:6px;vertical-align:-1px"></i>${r[0]} <b>€${fmt(r[3],0)}m</b> · ${fmt(r[3]/tot*100,0)}%${r[1]!=null?' · '+fmt(r[1]/1000,0)+' GWh at €'+fmt(r[2],1)+'/MWh':''}</span>`).join('');
  return `<svg viewBox="0 0 ${W2} 48" style="display:block;width:100%;height:auto">${segs}</svg>
   <div style="display:flex;gap:10px 22px;flex-wrap:wrap;margin-top:10px;font-size:13px;color:var(--t2)">${leg}</div>`;})();
 const billPanel=`<div class="panel" style="margin-bottom:14px"><h3>The power bill · first full year · €${fmt(total,0)}m · ${fmt(load/1e6,2)} TWh at €${fmt(unit,1)}/MWh plus the reliability charge</h3>${bar}
  <p class="muted" style="margin-top:8px">Same invoice as the Power SPV model: €${fmt(y1b.rev,0)}m energy revenue there, plus the €${fmt(relFee,0)}m battery reliability charge.</p></div>`;

 // ---------- 2 · what it costs to build ----------
 const it=DCLOAD.itMW, pue=d.firmMW/it, ov=d.firmMW-it;
 const B=computeBattery(M.battery);
 const powerCap=W.totalCapex+S.totalCapex+B.capex+lineMW()*M.conn.directPer100/100;
 const shellLo=10, shellHi=12, chipLo=25, chipHi=30;
 const buildKpis=`<div class="kpis">
   ${kpiM([['Power, per MW of connection','€'+fmt(powerCap/d.firmMW,1),'m'],['Total, this model','€'+fmt(powerCap/1000,1),'bn']],'var(--acc)')}
   ${kpiM([['Powered shell, per MW of IT','€'+shellLo+'–'+shellHi,'m'],['At '+it+' MW of IT','€'+fmt(it*shellLo/1000,1)+'–'+fmt(it*shellHi/1000,1),'bn']])}
   ${kpiM([['Chips, per MW of IT','€'+chipLo+'–'+chipHi,'m'],['At '+it+' MW of IT','€'+fmt(it*chipLo/1000,1)+'–'+fmt(it*chipHi/1000,1),'bn']],'#ffb23e')}
   ${kpiM([['All in','€'+fmt((it*shellLo+it*chipLo+powerCap)/1000,0)+'–'+fmt((it*shellHi+it*chipHi+powerCap)/1000,0),'bn'],['Of which power',fmt(powerCap/(it*shellLo+it*chipLo+powerCap)*100,0),'%']])}</div>`;
 const buildPanel=`<div class="panel" style="margin-bottom:14px"><h3>What it costs to build · PUE ${fmt(pue,2)} · ${fmt(d.firmMW,0)} MW at the connection, ${it} MW at the chips</h3>
   ${pueBar()}
   <p class="sub" style="margin-top:10px">Shell and chips are market benchmarks per MW of critical IT load, not project quotes. Power is this model, live: the parks, the battery, the lines and the substation.</p>
  </div>`;

 // ---------- 3 · the three players ----------
 const SP=computeSPV(M.dc.dcPrice), y1=SP.rows.find(r=>r.y===FF)||{rev:0,bRev:0,gridCost:0,resPPA:0,opex:0,ebitda:0};
 const spvRev=y1.rev+y1.bRev, spvCost=y1.resPPA+y1.gridCost+y1.opex, spvEb=y1.ebitda;
 const opsLo=it*0.08, opsHi=it*0.12;             // €m/yr · facility O&M ex power, market benchmark
 const pcard=(name,col,tint,ico,rows2)=>`<button class="castCard" style="cursor:default" onclick="void 0">
   <div class="top"><span class="ico" style="background:${tint};color:${col}">${ico}</span></div>
   <h5>${name}</h5>
   <p class="role">${rows2.role}</p>
   <div class="mets">${rows2.mets.map(m=>`<div class="met"><span>${m[0]}</span><b>${m[1]}</b></div>`).join('')}</div>
   <div class="jump" style="color:${col}">${rows2.foot}</div>
  </button>`;
 const players=`<div class="panel" style="margin-bottom:14px"><h3>The data center universe · who builds what, who pays what</h3>
  <div class="castGrid" style="margin-top:6px">
   ${pcard('Power SPV','#12b95a','rgba(0,154,68,.15)',ICO.spv,{
     role:'Builds and owns the lines, the substation and the battery. Buys from the parks and the grid, sells firm power on.',
     mets:[['CAPEX','€'+fmt(powerCap/1000,1)+'bn'],['Revenue /yr','€'+fmt(spvRev,0)+'m'],['OPEX /yr (energy in)','€'+fmt(spvCost,0)+'m'],['EBITDA /yr','€'+fmt(spvEb,0)+'m'],['Margin',fmt(spvRev>0?spvEb/spvRev*100:0,0)+'%']],
     foot:'This model, live'})}
   ${pcard('The landlord','#eaf2f8','rgba(234,242,248,.10)',ICO.state,{
     role:'Builds the powered shell and leases it. Power is passed through to the tenant.',
     mets:[['CAPEX (shell)','€'+fmt(it*shellLo/1000,1)+'–'+fmt(it*shellHi/1000,1)+'bn'],['Per MW of IT','€'+shellLo+'–'+shellHi+'m'],['OPEX /yr (facility)','€'+fmt(opsLo,0)+'–'+fmt(opsHi,0)+'m']],
     foot:'Market benchmarks per MW of IT'})}
   ${pcard('The compute tenant','#ffb23e','rgba(255,178,62,.12)',ICO.dc,{
     role:'Owns the chips, buys the power, pays the lease.',
     mets:[['CAPEX (chips)','€'+fmt(it*chipLo/1000,1)+'–'+fmt(it*chipHi/1000,1)+'bn'],['Per MW of IT','€'+chipLo+'–'+chipHi+'m'],['Power /yr','€'+fmt(total,0)+'m']],
     foot:'Market benchmarks per MW of IT'})}
  </div>
 </div>`;

 return head+billPanel+buildKpis+buildPanel+players;
}
