function pricesPage(){
 const nav=pageHead('Prices','Austrian day-ahead, 2015 to 2026.','',null)+
  `<div class="panel" style="margin-bottom:14px"><div style="display:flex;align-items:center;flex-wrap:wrap;gap:6px"><div class="seg">
   ${[['capture','Capture prices'],['dist','Distribution'],['arb','Battery spreads'],['neg','Negative hours'],['mix','Austria grid mix'],['raw','Raw data']]
     .map(t=>`<button class="${priceTab===t[0]?'on':''}" onclick="priceTab='${t[0]}';render()">${t[1]}</button>`).join('')}</div>
   ${priceTab==='arb'?`<div class="seg" style="margin-left:10px">${[['2','2h'],['4','4h'],['6','6h'],['8','8h']].map(d=>`<button class="${arbDur===d[0]?'on':''}" onclick="arbDur='${d[0]}';render()">${d[1]}</button>`).join('')}</div>
   <div class="seg" style="margin-left:8px">${[['year','By year'],['month','By month'],['dur','By duration'],['conc','Concentration']].map(v=>`<button class="${arbView===v[0]?'on':''}" onclick="arbView='${v[0]}';render()">${v[1]}</button>`).join('')}</div>`:''}
   ${priceTab==='neg'?`<div class="seg" style="margin-left:10px">${[['year','By year'],['hour','By hour of day'],['month','By month'],['heat','Year by hour']].map(v=>`<button class="${negView===v[0]?'on':''}" onclick="negView='${v[0]}';render()">${v[1]}</button>`).join('')}</div>`:''}
   </div></div>`;
 if(priceTab==='dist'){setTimeout(drawPxDist,0);return nav+pdPage();}
 if(priceTab==='arb'){setTimeout(drawArb,0);return nav+arbPage();}
 if(priceTab==='neg'){setTimeout(drawNeg,0);return nav+negPage();}
 if(priceTab==='mix'){setTimeout(drawGridMix,0);return nav+`<div class="chart tall" id="mixmain"></div>`;}
 if(priceTab==='raw'){setTimeout(pxBoot,0);return nav+pxPage();}
 setTimeout(drawPrices,0);
 const yrs=['2015','2016','2017','2018','2019','2020','2021','2022','2023','2024','2025'];
 const py=PRICES.per_year[priceYear], bl=py.baseload, wc=py.wind, sc=py.solar;
 const wCF=effCF(M.wind)*100, sCF=effCF(M.solar)*100;
 const ex=['2019','2020','2021','2023','2024','2025'], avg=k=>ex.reduce((s,y)=>s+PRICES.per_year[y][k],0)/ex.length;
 const avgBl=avg('baseload'),avgW=avg('wind'),avgS=avg('solar');
 const sel=`<div class="panel" style="margin-bottom:14px"><div style="display:flex;gap:18px;align-items:center;flex-wrap:wrap">
   <div class="inp" style="flex:1;min-width:240px;margin-bottom:0"><label>Curve year<b>${priceYear}</b></label>
   <input type="range" min="2015" max="2025" step="1" value="${priceYear}" oninput="priceYear=String(this.value);render()"></div>
   </div></div>`;
 const kpis=`<div class="kpis">
   ${kpi('Baseload '+priceYear,'€'+fmt(bl,0),'/MWh')}
   <div class="kpi" style="border-color:var(--wind)"><div class="l">Wind capture ${priceYear}</div><div class="v" style="color:var(--wind)">€${fmt(wc,0)}<small> ${fmt(wc/bl*100,0)}% base · CF ${fmt(wCF,0)}%</small></div></div>
   <div class="kpi" style="border-color:var(--solar)"><div class="l">Solar capture ${priceYear}</div><div class="v" style="color:var(--solar)">€${fmt(sc,0)}<small> ${fmt(sc/bl*100,0)}% base · CF ${fmt(sCF,0)}%</small></div></div>
   ${kpi('7-yr avg (ex-2022)','W €'+fmt(avgW,0)+' / S €'+fmt(avgS,0),'/MWh')}</div>`;
 const BASIS={'metered':'metered','part-metered':'part metered','measured shape':'measured shape'};
 const trow=(y,extra)=>{const p=PRICES.per_year[y];return `<tr class="${y===priceYear?'tot':''}"><td>${y}${extra||''}</td><td>€${fmt(p.baseload,0)}</td><td style="color:var(--wind)">€${fmt(p.wind,0)}</td><td>${fmt(p.wind/p.baseload*100,0)}%</td><td style="color:var(--solar)">€${fmt(p.solar,0)}</td><td>${fmt(p.solar/p.baseload*100,0)}%</td><td class="muted" style="font-size:12.5px">${BASIS[p.basis]||p.basis}</td></tr>`;};
 const table=`<div class="panel" style="margin-top:14px"><h3>Capture prices 2015-2025 <span class="seg" style="margin-left:12px;text-transform:none"><button class="${priceView==='chart'?'on':''}" onclick="priceView='chart';render()">Chart</button><button class="${priceView==='table'?'on':''}" onclick="priceView='table';render()">Table</button></span></h3>
   ${priceView==='chart'?`<div class="chart tall" id="pr_trend" style="border:none;padding:0"></div>`:`<table><thead><tr><th>Year</th><th>Baseload</th><th>Wind cap</th><th>Wind %</th><th>Solar cap</th><th>Solar %</th><th>Basis</th></tr></thead><tbody>
   ${yrs.map(y=>trow(y)).join('')}
   ${trow('2026',' <span class="muted" style="font-size:12px">part year</span>')}
   <tr class="tot"><td>Avg ex-2022</td><td>€${fmt(avgBl,0)}</td><td style="color:var(--wind)">€${fmt(avgW,0)}</td><td>${fmt(avgW/avgBl*100,0)}%</td><td style="color:var(--solar)">€${fmt(avgS,0)}</td><td>${fmt(avgS/avgBl*100,0)}%</td><td class="muted" style="font-size:12.5px">six full years</td></tr>
   </tbody></table>`}</div>`;
 return nav+kpis+sel+`<div class="charts"><div class="chart tall" id="pr_daily"></div><div class="chart tall" id="pr_season"></div></div>`+table;
}

