/* ================= yield funnel: gross -> plant -> line -> delivered ================= */

function bridgePanel(sec){
 const isW=sec==='wind', a=M[sec], B=BENCH[sec];
 const g=a.grossCF*8760, p=g*(1-a.loss), d=effCF(a)*8760;
 const gap=(p/B.roll-1)*100;
 const tAdj=isW?null:B.tracker?B.roll*(1+B.tracker.uplift/100):null;
 return `<div class="panel" style="margin-bottom:14px"><h3>${isW?'Wind':'Solar'} · yield bridge, resource to the data center</h3>
   ${funnelSVG(sec)}</div>`;
}
function funnelSVG(sec){
 const a=M[sec], isW=sec==='wind', B=BENCH[sec];
 const col=isW?'#4aa8ff':'#ffb23e';
 const gross=a.grossCF*8760, plant=gross*(1-a.loss), del=plant*(1-(a.lineLoss||0));
 const W=1180,x0=90,x3=W-250,cy=150,maxH=190;
 const hOf=v=>Math.max(8,v/gross*maxH);
 const xs=[x0,x0+(x3-x0)*0.44,x3], V=[gross,plant,del];
 const top=i=>cy-hOf(V[i])/2, bot=i=>cy+hOf(V[i])/2;
 const body=`${xs.map((x,i)=>`${x},${top(i)}`).join(' ')} ${xs.map((x,i)=>`${x},${bot(i)}`).reverse().join(' ')}`;
 const lossSeg=(i,label,pctTxt,amt)=>{
  const xm=(xs[i]+xs[i+1])/2;
  return `<polygon points="${xs[i]},${top(i)} ${xs[i+1]},${top(i+1)} ${xs[i+1]},${top(0)} ${xs[i]},${top(0)}" fill="url(#hatch)" stroke="#ff6b6b" stroke-width=".6" opacity=".9"/>
   <polygon points="${xs[i]},${bot(i)} ${xs[i+1]},${bot(i+1)} ${xs[i+1]},${bot(0)} ${xs[i]},${bot(0)}" fill="url(#hatch)" stroke="#ff6b6b" stroke-width=".6" opacity=".9"/>
   <text x="${xm}" y="${top(0)-24}" fill="#ff6b6b" font-size="13" text-anchor="middle" font-weight="700">−${pctTxt}</text>
   <text x="${xm}" y="${top(0)-10}" fill="#ff8b8b" font-size="13" text-anchor="middle">${label}</text>
   <text x="${xm}" y="${bot(0)+16}" fill="#ff6b6b" font-size="13" text-anchor="middle">−${fmt(amt,0)} FLH</text>`;
 };
 const node=(i,ttl)=>`<line x1="${xs[i]}" y1="${top(i)-4}" x2="${xs[i]}" y2="${bot(i)+4}" stroke="#e8eef3" stroke-width="1.4" opacity=".6"/>
   <text x="${xs[i]}" y="${bot(0)+42}" fill="#e8eef3" font-size="14" text-anchor="middle" font-weight="680">${fmt(V[i],0)} FLH</text>
   <text x="${xs[i]}" y="${bot(0)+59}" fill="#94a2b1" font-size="13" text-anchor="middle">${pct(V[i]/8760,1)} capacity factor</text>
   <text x="${xs[i]}" y="${bot(0)+77}" fill="#7d8fa1" font-size="13" text-anchor="middle">${ttl}</text>`;
 return `<svg viewBox="0 0 ${W} ${bot(0)+100}" width="100%" style="display:block">
  <defs><pattern id="hatch" width="6" height="6" patternTransform="rotate(45)" patternUnits="userSpaceOnUse">
    <rect width="6" height="6" fill="#ff6b6b" opacity=".13"/><line x1="0" y1="0" x2="0" y2="6" stroke="#ff6b6b" stroke-width="1.6" opacity=".38"/></pattern></defs>
  <line x1="${x0}" y1="${top(0)}" x2="${x3}" y2="${top(0)}" stroke="#5b6b7d" stroke-width="1" stroke-dasharray="5,4"/>
  <line x1="${x0}" y1="${bot(0)}" x2="${x3}" y2="${bot(0)}" stroke="#5b6b7d" stroke-width="1" stroke-dasharray="5,4"/>
  <text x="${x0-8}" y="${top(0)-6}" fill="#7d8fa1" font-size="13" text-anchor="end">if nothing</text>
  <text x="${x0-8}" y="${top(0)+5}" fill="#7d8fa1" font-size="13" text-anchor="end">were lost</text>
  <polygon points="${body}" fill="${col}" opacity="0.44" stroke="${col}" stroke-width="1.8"/>
  ${lossSeg(0,isW?'wake, availability, electrical':'soiling, inverter, availability',pct(a.loss,1),gross-plant)}
  ${lossSeg(1,'direct line, '+(isW?'~14.7':'~9.1')+' km',pct(a.lineLoss||0,1),plant-del)}
  ${node(0,'modelled gross P50')}${node(1,'at the plant meter')}${node(2,'delivered to the DC')}
  <text x="${x3+20}" y="${cy-6}" fill="${col}" font-size="14" font-weight="700">${fmt(a.mw,0)} ${isW?'MW':'MWp'}</text>
  <text x="${x3+20}" y="${cy+12}" fill="#94a2b1" font-size="13">${fmt(del*a.mw/1000,0)} GWh/yr to the DC</text>
 </svg>`;
}

