/* ---------------- raw hourly price explorer ---------------- */
function pxPage(){
 return `<div class="panel" style="margin-bottom:14px">
   <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:flex-end">
    <div><label class="muted" style="font-size:12.5px;display:block;margin-bottom:4px">From</label>
     <input id="pxFrom" type="date" value="2024-01-01" onchange="pxDraw()" style="background:var(--panel2);border:1px solid var(--line);border-radius:7px;color:var(--txt);padding:6px 9px"></div>
    <div><label class="muted" style="font-size:12.5px;display:block;margin-bottom:4px">To</label>
     <input id="pxTo" type="date" value="2026-07-07" onchange="pxDraw()" style="background:var(--panel2);border:1px solid var(--line);border-radius:7px;color:var(--txt);padding:6px 9px"></div>
    <div><label class="muted" style="font-size:12.5px;display:block;margin-bottom:4px">Price at or below</label>
     <input id="pxMax" type="number" placeholder="any" onchange="pxDraw()" style="width:110px;background:var(--panel2);border:1px solid var(--line);border-radius:7px;color:var(--txt);padding:6px 9px"></div>
    <div><label class="muted" style="font-size:12.5px;display:block;margin-bottom:4px">Price at or above</label>
     <input id="pxMin" type="number" placeholder="any" onchange="pxDraw()" style="width:110px;background:var(--panel2);border:1px solid var(--line);border-radius:7px;color:var(--txt);padding:6px 9px"></div>
    <button class="chip" onclick="document.getElementById('pxMax').value=-0.01;pxDraw()">Negative only</button>
    <button class="chip reset" onclick="document.getElementById('pxMin').value='';document.getElementById('pxMax').value='';pxDraw()">Clear</button>
    <div style="margin-left:auto;display:flex;gap:6px">
     <button class="chip" onclick="pxDl(true)">CSV · filtered</button>
     <button class="chip" onclick="pxDl(false)">CSV · all hours</button></div>
   </div>
   <div class="muted" id="pxStatus" style="margin-top:9px">Loading the hourly record…</div></div>
  <div class="chartWrap"><div class="chart tall" id="px_chart"></div></div>
  <div id="pxTable" style="margin-top:14px"></div>
  <div class="info" style="margin-top:12px">Hourly Austrian day-ahead wholesale prices, ${NEGP.totalHours.toLocaleString('en-US')} prints from ${NEGP.byYear[0].year} to July 2026, in €/MWh with the local timestamp exactly as supplied. Source: Ember European wholesale electricity prices. This is public market data, not Burgenland Energie material, so it sits outside the access code and downloads unencrypted. The table shows the first 500 matching rows; the CSV carries every one.</div>`;
}
async function pxBoot(){
 if(pxRows||pxBusy)return pxDraw();
 pxBusy=true;
 try{
  const r=await fetch('prices_hourly.csv');
  const t=await r.text();
  const ls=t.split('\n'); pxRows=[];
  for(let i=1;i<ls.length;i++){const L=ls[i];if(!L)continue;const c=L.indexOf(',');
   pxRows.push([L.slice(0,c),+L.slice(c+1)]);}
  pxBusy=false; pxDraw();
 }catch(e){pxBusy=false;const s=document.getElementById('pxStatus');if(s)s.textContent='Could not load prices_hourly.csv: '+e.message;}
}
function pxFilter(){
 if(!pxRows)return [];
 const f=(document.getElementById('pxFrom')||{}).value||'2015-01-01';
 const t=((document.getElementById('pxTo')||{}).value||'2026-12-31')+' 23:59';
 const lo=(document.getElementById('pxMin')||{}).value, hi=(document.getElementById('pxMax')||{}).value;
 const L=lo===''||lo==null?-1e9:+lo, H=hi===''||hi==null?1e9:+hi;
 return pxRows.filter(r=>r[0]>=f&&r[0]<=t&&r[1]>=L&&r[1]<=H);
}
function pxDraw(){
 const s=document.getElementById('pxStatus'); if(!s)return;
 if(!pxRows){s.textContent=pxBusy?'Loading the hourly record…':'Not loaded.';return;}
 const F=pxFilter();
 s.innerHTML=`<b>${F.length.toLocaleString('en-US')}</b> hours match, of ${pxRows.length.toLocaleString('en-US')} in the record.`+
  (F.length?` Mean €${fmt(F.reduce((a,r)=>a+r[1],0)/F.length,1)}/MWh · min €${fmt(Math.min(...F.map(r=>r[1])),1)} · max €${fmt(Math.max(...F.map(r=>r[1])),1)} · ${F.filter(r=>r[1]<0).length.toLocaleString('en-US')} below zero.`:'');
 const step=Math.max(1,Math.ceil(F.length/6000)), P=F.filter((_,i)=>i%step===0);
 Plotly.react('px_chart',[{x:P.map(r=>r[0]),y:P.map(r=>r[1]),type:'scatter',mode:'lines',
   line:{color:'#ff6b6b',width:0.8},hovertemplate:'%{x}: €%{y:.2f}/MWh<extra></extra>'}],
  lay('Hourly day-ahead price'+(step>1?' · thinned 1 in '+step+' for drawing':''),
   {showlegend:false,hovermode:'closest',yaxis:{title:{text:'€/MWh',font:{size:12}},gridcolor:'#1c2531',
     zeroline:true,zerolinecolor:'#ff6b6b',zerolinewidth:1.2},
    xaxis:{gridcolor:'#1c2531',type:'category',nticks:10,rangeslider:{visible:true,thickness:0.07,bgcolor:'#111a24'}}}),CFG);
 const show=F.slice(0,500);
 document.getElementById('pxTable').innerHTML=
  `<div style="max-height:460px;overflow:auto;border:1px solid var(--line);border-radius:8px">
   <table style="width:100%;border-collapse:collapse;font-size:12.5px;font-variant-numeric:tabular-nums">
   <thead style="position:sticky;top:0;background:#16202c"><tr>
    <th style="text-align:left;padding:5px 10px">datetime_local</th>
    <th style="text-align:right;padding:5px 10px">price_eur_mwh</th></tr></thead><tbody>
   ${show.map(r=>`<tr><td style="padding:2px 10px;border-top:1px solid var(--gridfaint)">${r[0]}</td>
    <td style="padding:2px 10px;border-top:1px solid var(--gridfaint);text-align:right;${r[1]<0?'color:#ff6b6b':''}">${r[1].toFixed(2)}</td></tr>`).join('')}
   </tbody></table></div>
   ${F.length>500?`<div class="muted" style="margin-top:7px">Showing the first 500 of ${F.length.toLocaleString('en-US')} matching rows. Use CSV · filtered for the rest.</div>`:''}`;
}
function pxDl(filtered){
 const R=filtered?pxFilter():pxRows; if(!R||!R.length)return;
 const txt='datetime_local,price_eur_mwh\r\n'+R.map(r=>r[0]+','+r[1].toFixed(2)).join('\r\n');
 const b=new Blob([txt],{type:'text/csv;charset=utf-8'});
 const a=document.createElement('a');a.href=URL.createObjectURL(b);
 a.download='austria_day_ahead_hourly'+(filtered?'_filtered':'_full')+'.csv';a.click();
 setTimeout(()=>URL.revokeObjectURL(a.href),4000);
}

