function splashHTML(){
 const chip=(ci,ico,v,u,l)=>`<div class="sChip" style="--ci:${ci}"><span class="ic">${ico}</span>
   <span><span class="sv">${v}<small>${u}</small></span><span class="sl" style="display:block">${l}</span></span></div>`;
 return `<div id="splash">
  <div class="splashScene">${landingScene('scSplash',900,'sceneFill')}
   <div style="position:absolute;inset:0;background:radial-gradient(ellipse at 50% 42%,rgba(7,11,16,.34),rgba(7,11,16,.86))"></div></div>
  <div class="splashInner">
   <div class="splashKicker" style="display:flex;align-items:center;justify-content:center;gap:10px">${FLAG.at}<span>Burgenland · Austria</span></div>
   <h1 class="wmk splashWm"><span class="nk">Green Data Campus</span>Nickelsdorf</h1>
   <div class="splashRule"></div>
   <div class="splashStats">
    ${chip('#8ef0b8',SICO.dc,fmt(M.dc.firmMW,0),' MW','Data center')}
    ${chip('#4aa8ff',SICO.wind,fmt(M.wind.mw,0),' MW','Wind')}
    ${chip('#ffb23e',SICO.sun,fmt(M.solar.mw,0),' MWp','Solar')}
    ${chip('#b98cff',SICO.batt,fmt(M.battery.powerMW,0)+' MW',' · '+fmt(M.battery.durationH,0)+'h','Storage')}
    ${chip('#46b45a',SICO.line,'110',' kV','Private direct line')}
   </div>
   <button class="splashBtn" onclick="closeSplash()">Explore the project<span class="arr">→</span></button>
  </div>
  <div class="splashFoot" aria-label="Project partners">
   <a class="brandLink splashPartner splashPartnerNx" href="https://nexwell.com" target="_blank" rel="noopener noreferrer" title="Nexwell">${NXLOGO('')}</a>
   <span style="color:#3d5164;font-size:26px">×</span>
   <a class="brandLink splashPartner splashPartnerBe" href="https://www.burgenlandenergie.at" target="_blank" rel="noopener noreferrer" title="Burgenland Energie">${BELOGO('',true)}</a>
  </div>
 </div>`;
}
function closeSplash(){
 const s=document.getElementById('splash'); if(!s)return;
 s.classList.add('out');
 try{sessionStorage.setItem('gdcSplash','1');}catch(e){}
 setTimeout(()=>s.remove(),700);
}
function maybeSplash(){
 let seen=false; try{seen=sessionStorage.getItem('gdcSplash')==='1';}catch(e){}
 if(seen)return;
 document.body.insertAdjacentHTML('beforeend',splashHTML());
 document.addEventListener('keydown',function esc(e){if(e.key==='Escape'){closeSplash();document.removeEventListener('keydown',esc);}});
}

/* ---------------- the Overview page ---------------- */
/* a small inline sparkline. No chart library, so it stays crisp and costs nothing. */
function spark(vals,opt){
 const o=Object.assign({w:260,h:52,col:'#46b45a',fill:true,dot:true,pad:5},opt||{});
 const v=vals.filter(x=>x!=null&&!isNaN(x));
 if(v.length<2)return '';
 const mn=Math.min(...v), mx=Math.max(...v), rng=(mx-mn)||1;
 const X=i=>o.pad+i*(o.w-2*o.pad)/(v.length-1), Y=x=>o.h-o.pad-(x-mn)/rng*(o.h-2*o.pad);
 const pts=v.map((x,i)=>`${X(i).toFixed(1)},${Y(x).toFixed(1)}`).join(' ');
 const area=o.fill?`<polygon points="${o.pad},${o.h} ${pts} ${o.w-o.pad},${o.h}" fill="${o.col}" opacity=".12"/>`:'';
 const last=o.dot?`<circle cx="${X(v.length-1).toFixed(1)}" cy="${Y(v[v.length-1]).toFixed(1)}" r="3" fill="${o.col}"/>`:'';
 return `<svg class="spark" viewBox="0 0 ${o.w} ${o.h}" preserveAspectRatio="none" aria-hidden="true">
   ${area}<polyline points="${pts}" fill="none" stroke="${o.col}" stroke-width="1.8" stroke-linejoin="round" stroke-linecap="round"/>${last}</svg>`;
}

