function BELOGO(st,dark,fontPx){const b=dark===false?"#111111":"#ffffff";
 return `<span style="display:inline-flex;align-items:center;gap:${fontPx?Math.round(fontPx*0.5):10}px"><svg style="${st};width:auto;display:block" viewBox="0 0 24.6 32.76" xmlns="http://www.w3.org/2000/svg" aria-label="Burgenland Energie"><path d="M22.92,8.52 C22.92,3.84 19.08,0 14.28,0 L1.92,0 C0.84,0 0,0.72 0,1.8 L0,30.84 C0,31.92 0.84,32.76 1.92,32.76 L15.96,32.76 L15.96,17.04 C19.92,16.32 22.92,12.84 22.92,8.52 Z" fill="${b}"/><circle cx="15.96" cy="24.12" r="8.64" fill="#FFCC07"/></svg><span style="font-family:Inter,'Segoe UI',sans-serif;font-weight:640;letter-spacing:-.005em;font-size:${fontPx?fontPx+'px':'calc(0px + 1em)'};color:${b};line-height:1;white-space:nowrap">Burgenland Energie</span></span>`;}
/* Burgenland Energie's own direct-line project list, PDF dated 06/2026, item
   "Renewable energy projects for direct line - Overview". Distances, capacities, statuses and
   completion dates are all theirs. d = km of direct line, as they state it. */


function projStats(){
 const w=PROJ.filter(p=>p.t==='w'), s=PROJ.filter(p=>p.t==='s');
 const sum=a=>a.reduce((x,p)=>x+p.mw,0), wm=a=>a.reduce((x,p)=>x+p.mw*p.d,0)/Math.max(1,sum(a));
 const near=PROJ.filter(p=>p.d<=5.5), far=PROJ.filter(p=>p.d>=18);
 return {wMW:sum(w),sMW:sum(s),tot:sum(PROJ),wKm:wm(w),sKm:wm(s),allKm:wm(PROJ),
   nearMW:sum(near),farMW:sum(far),maxKm:Math.max(...PROJ.map(p=>p.d)),
   opsMW:sum(PROJ.filter(p=>p.st==='In operations')),rtbMW:sum(PROJ.filter(p=>p.st==='Ready to build')),
   planMW:sum(PROJ.filter(p=>p.st==='In planning'||p.st==='In zoning'||p.st==='Zoned'))};
}

/* the parks and the line, drawn to BE's own distances, with the receiving end drawn in:
   grid, campus substation, battery and data center on the left, every park on the right.
   Not a map: a distance schematic, so nothing about the geography is invented. */
function topologySVG(){
 const P=[...PROJ].sort((a,b)=>a.d-b.d);
 const W=1180, rowH=27, top=88, H=Math.max(top+P.length*rowH+52,560);
 const x0=560, x1=1140, maxD=28;
 const X=d=>x0+d/maxD*(x1-x0);
 const col=p=>p.t==='w'?'#4aa8ff':'#ffb23e';
 const dash=p=>(p.st==='In operations'||p.st==='Ready to build')?'':' stroke-dasharray="4 4"';
 const codS=d=>String(d).replace('Direct line ','').replace(/^\d\d\.\d\d\.(\d{4})$/,'$1');
 const rows=P.map((p,i)=>{
  const y=top+i*rowH+rowH/2, xe=X(p.d), r=Math.max(3.8,Math.sqrt(p.mw)*0.92);
  return `<g class="tpRow">
    <text x="${x0-14}" y="${y+4}" font-size="12.5" fill="#c3d1c9" text-anchor="end" font-family="Inter,sans-serif">${p.name}</text>
    <line x1="${x0}" y1="${y}" x2="${xe}" y2="${y}" stroke="${col(p)}" stroke-width="1.6" opacity=".55"${dash(p)}/>
    <circle cx="${xe}" cy="${y}" r="${r.toFixed(1)}" fill="${col(p)}" opacity=".88"/>
    <text x="${p.d>=18?xe-r-9:xe+r+9}" y="${p.d>=18?y-7:y+4}" font-size="12" fill="#93a49a" text-anchor="${p.d>=18?'end':'start'}" font-family="Inter,sans-serif">${p.mw} MW${p.t==='s'?'p':''} · ${p.d} km · ${p.st} · <tspan fill="#c3d1c9">COD ${codS(p.due)}</tspan></text>
    <title>${p.name} · ${p.mw} MW${p.t==='s'?'p':''}, ${p.d} km of direct line, ${p.st}, due ${p.due}</title></g>`;
 }).join('');
 const ticks=[0,5,10,15,20,25].map(d=>`<line x1="${X(d)}" y1="${top-16}" x2="${X(d)}" y2="${top+P.length*rowH+6}" stroke="#243029" stroke-width="1"/>
   <text x="${X(d)}" y="${top-24}" font-size="11" fill="#7d8f84" text-anchor="middle" font-family="Inter,sans-serif">${d} km</text>`).join('');
 // ---------- the receiving end, on the left ----------
 const bx=(x,y,w,h,stroke,fill)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="${fill||'#151d19'}" stroke="${stroke}" stroke-width="1.3"/>`;
 const t=(x,y,txt2,o)=>{o=o||{};return `<text x="${x}" y="${y}" font-size="${o.s||11.5}" fill="${o.f||'#93a49a'}"${o.a?` text-anchor="${o.a}"`:''}${o.w?` font-weight="${o.w}"`:''} font-family="Inter,sans-serif">${txt2}</text>`;};
 const GRID='#8fa3bb', ACC='#46b45a', BAT='#b98cff', TXT='#e6efe9';
 const gx=36, gy=64;
 const grid=`<g class="tpN">
   ${t(gx+75,gy-26,'APG 380 kV',{a:'middle',f:'#ff8b8b',s:11.5,w:700})}${t(gx+75,gy-13,'Netzverstärkung Ost',{a:'middle',f:'#ff8b8b',s:10.5})}
   <line x1="${gx+75}" y1="${gy-8}" x2="${gx+75}" y2="${gy}" stroke="#ff6b6b" stroke-width="2"/>
   ${bx(gx,gy,150,42,GRID)}${t(gx+75,gy+18,'UW Zurndorf',{a:'middle',f:TXT,s:12.5,w:700})}${t(gx+75,gy+33,'grid connection · APG / NEB',{a:'middle',s:10.5})}
   ${bx(gx,gy+56,150,36,GRID)}${t(gx+75,gy+72,'UW Andau',{a:'middle',f:'#b9c6d2',s:12,w:600})}${t(gx+75,gy+85,'fed through Zurndorf',{a:'middle',s:10})}
   <line x1="${gx+75}" y1="${gy+42}" x2="${gx+75}" y2="${gy+56}" stroke="${GRID}" stroke-width="1.4"/></g>`;
 const sy=228;
 const feeders=[0,1,2].map(i=>`<path d="M ${gx+118} ${gy+42} C ${gx+190} ${gy+96+i*10}, ${gx+40+i*14} ${sy-58}, ${gx+62+i*38} ${sy}" fill="none" stroke="${ACC}" stroke-width="1.5" opacity=".8"/>`).join('')
  +t(gx+188,gy+118,'3 × 3.5 km',{f:ACC,s:11.5,w:700})+t(gx+188,gy+131,'110 kV feeders → 3N/2',{f:ACC,s:10.5});
 const sub=`<g class="tpN">${bx(gx,sy,224,54,ACC,'#12241a')}
   ${t(gx+112,sy+20,'Campus substation · Power SPV',{a:'middle',f:TXT,s:12.5,w:700})}
   ${t(gx+112,sy+38,'110 kV · built, owned &amp; financed by the SPV',{a:'middle',f:ACC,s:10.5})}</g>`;
 const by=sy+78;
 const batt=`<g class="tpN"><line x1="${gx+112}" y1="${sy+54}" x2="${gx+112}" y2="${by}" stroke="${BAT}" stroke-width="1.8"/>
   ${bx(gx,by,224,52,BAT,'#1b1526')}
   ${t(gx+112,by+20,`Battery ${nfm(M.battery.powerMW)} MW · ${fmt(M.battery.powerMW*M.battery.durationH/1000,1)} GWh`,{a:'middle',f:TXT,s:12.5,w:700})}
   ${t(gx+112,by+38,`${fmt(M.battery.durationH,0)} h · RTE ${pct(M.battery.rte,0)} · buried 110 kV tie`,{a:'middle',f:BAT,s:10.5})}</g>`;
 const dy=by+76;
 const dc=`<g class="tpN"><line x1="${gx+112}" y1="${by+52}" x2="${gx+112}" y2="${dy}" stroke="${TXT}" stroke-width="1.6"/>
   ${bx(gx,dy,224,54,'#eaf2f8','#161e26')}
   ${t(gx+112,dy+21,`${nfm(M.dc.firmMW)} MW data center`,{a:'middle',f:'#ffffff',s:13.5,w:700})}
   ${t(gx+112,dy+39,`${nfm(Math.round(M.dc.firmMW/TECH.pue))} MW IT · Nickelsdorf`,{a:'middle',s:10.5})}</g>`;
 const trunkY=sy+27;
 const trunk=`<path d="M ${gx+224} ${trunkY} C ${gx+330} ${trunkY}, ${x0-90} ${trunkY}, ${x0-2} ${trunkY}" fill="none" stroke="${ACC}" stroke-width="2.2" stroke-dasharray="7 4" opacity=".85"/>
   ${t(gx+248,trunkY+19,'buried 110 kV direct lines →',{f:ACC,s:11.5,w:600})}`;
 return `<svg viewBox="0 0 ${W} ${H}" class="topoSVG" style="display:block;width:100%;height:auto" role="img"
   aria-label="Every Burgenland Energie project on the direct line, placed by the line distance they quote, with the grid, the campus substation, the battery and the data center drawn on the left">
  ${ticks}
  <rect x="${x0-3}" y="${top-16}" width="6" height="${P.length*rowH+22}" rx="3" fill="#009a44" opacity=".9"/>
  <text x="${x0}" y="${top+P.length*rowH+34}" font-size="12.5" font-weight="600" fill="#46b45a" text-anchor="middle" font-family="Inter,sans-serif">GDC Nickelsdorf</text>
  ${grid}${feeders}${sub}${batt}${dc}${trunk}
  ${rows}
  <g transform="translate(${x0+8},30)">
   <circle cx="0" cy="-4" r="4.5" fill="#4aa8ff"/><text x="11" y="0" font-size="11.5" fill="#93a49a" font-family="Inter,sans-serif">wind</text>
   <circle cx="66" cy="-4" r="4.5" fill="#ffb23e"/><text x="77" y="0" font-size="11.5" fill="#93a49a" font-family="Inter,sans-serif">solar</text>
   <line x1="140" y1="-4" x2="176" y2="-4" stroke="#93a49a" stroke-width="1.5"/><text x="184" y="0" font-size="11.5" fill="#93a49a" font-family="Inter,sans-serif">operating / ready to build</text>
   <line x1="352" y1="-4" x2="388" y2="-4" stroke="#93a49a" stroke-width="1.5" stroke-dasharray="4 4"/><text x="396" y="0" font-size="11.5" fill="#93a49a" font-family="Inter,sans-serif">planning / zoning</text>
   <text x="500" y="0" font-size="11.5" fill="#7d8f84" font-family="Inter,sans-serif">circle = capacity</text>
  </g>
 </svg>`;
}
function topologyPanel(){
 const S=projStats();
 return `<section class="sect">
   <div class="kick">The parks and the line</div>
   <h2 class="dsp">Fifteen parks feed one substation. Half the capacity sits within five kilometres.</h2>
   <div class="flowWrap" style="margin-top:18px;padding:14px 10px 6px">${topologySVG()}</div>
  </section>`;
}
