/* ================= motion runtime =================
   Transitions are anchored to the pointer, so a page appears to open from the control you
   pressed. Nothing here changes layout: the reveal is a clip-path, which is paint only, so
   Plotly still measures the true container width while a chart is drawing. */
let _lastClick={x:null,y:null};
document.addEventListener('pointerdown',e=>{_lastClick={x:e.clientX,y:e.clientY};},true);

function ripple(e){
 if(reduceMo())return;
 const t=e&&e.currentTarget; if(!t||!t.getBoundingClientRect)return;
 const r=t.getBoundingClientRect(), d=Math.max(r.width,r.height)*2.2;
 const s=document.createElement('span');
 s.className='rip';
 s.style.width=s.style.height=d+'px';
 s.style.left=((e.clientX-r.left))+'px';
 s.style.top=((e.clientY-r.top))+'px';
 t.appendChild(s);
 setTimeout(()=>s.remove(),640);
}

/* count a value into place instead of snapping it. Preserves prefixes, units and markup. */
function animateCounters(root){
 if(reduceMo())return;
 const sel='.kpi .v, .kpi .mv2, .figRow .n, .evCard .figure, .heroStrip .v, .pgHead .dsp';
 root.querySelectorAll(sel).forEach(el=>{
  if(el.dataset.ctd)return;
  const html=el.innerHTML;
  const m=html.match(/(-?\d[\d,]*\.?\d*)/);
  if(!m)return;
  const raw=m[1], target=parseFloat(raw.replace(/,/g,''));
  if(!isFinite(target)||Math.abs(target)>1e9||Math.abs(target)<0.0001)return;
  const dec=(raw.split('.')[1]||'').length;
  el.dataset.ctd='1';
  const t0=performance.now(), dur=680;
  const tick=now=>{
   const p=Math.min(1,(now-t0)/dur), e=1-Math.pow(1-p,3);
   if(p<1){
    const v=(target*e).toLocaleString('en-US',{minimumFractionDigits:dec,maximumFractionDigits:dec});
    el.innerHTML=html.replace(raw,v);
    requestAnimationFrame(tick);
   }else el.innerHTML=html;
  };
  requestAnimationFrame(tick);
 });
}

/* Reveal on scroll.
   The first version tagged the direct children of #main, which was right when a page was a stack of
   panels and wrong once a page became a handful of very tall sections: one reveal per screenful
   reads as no reveal at all. This walks down instead, and tags the units a reader perceives
   separately, the figures in a row, the cards in a grid, a panel's chart and its table and its
   note. Descent stops at anything that is not a layout container, so a parent and its child are
   never both tagged and nothing fades in while its own parent is still invisible.

   Stagger runs on position among siblings, capped, so a row of seven cards deals out rather than
   arriving at once but still finishes in under half a second. */
const RV_CONT='.sect,.panel,.figRow,.castGrid,.chain,.kpis,.charts,.grid,.cardRow,.cols,.cols3,.evRow,.assetGrid';
const RV_SKIP='svg,defs,script,style,thead,tbody,tr,td,th,.ctBar,.seg,#nav,.glShine,.segTh,.stBeats,.stHint';
const RV_MAX=140;
let _rvObs=null;
function armReveal(root){
 if(reduceMo())return;
 if(!_rvObs)_rvObs=new IntersectionObserver(es=>{
   es.forEach(x=>{if(x.isIntersecting){
     x.target.style.transitionDelay=((x.target._rvi||0)*68)+'ms';
     x.target.classList.add('in'); _rvObs.unobserve(x.target);}});
 },{rootMargin:'0px 0px -5% 0px',threshold:0.02});
 const out=[];
 const walk=(el,depth)=>{
  if(out.length>=RV_MAX)return;
  const kids=[...el.children];
  let n=0;
  for(const k of kids){
   if(out.length>=RV_MAX)return;
   if(!(k instanceof HTMLElement))continue;
   if(k.matches(RV_SKIP)||k.closest('svg'))continue;
   const h=k.getBoundingClientRect().height;
   if(h<18)continue;                                        // spacers and hairlines
   if(depth<4&&k.matches(RV_CONT)&&k.children.length>1){walk(k,depth+1);continue;}
   k.classList.add('rv'); k._rvi=Math.min(n++,6); out.push(k); _rvObs.observe(k);
  }
 };
 [...root.children].forEach((c,i)=>{
   if(i<1)return;                                           // the hero has its own entrance
   if(c.matches&&c.matches('.story'))return;                // the pinned stage manages itself
   if(c.matches(RV_CONT)&&c.children.length>1)walk(c,1);
   else {c.classList.add('rv'); c._rvi=0; _rvObs.observe(c);}
 });
}

/* the page transition itself */
let _pgBusy=false;
function transitionTo(fn){
 const m=document.getElementById('main');
 if(reduceMo()||_pgBusy){fn();afterRender();return;}
 _pgBusy=true;
 const W=innerWidth,H=innerHeight;
 const ox=_lastClick.x==null?50:Math.max(0,Math.min(100,_lastClick.x/W*100));
 const oy=_lastClick.y==null?12:Math.max(0,Math.min(100,_lastClick.y/H*100));
 m.classList.remove('pgIn');
 m.classList.add('pgOut');
 setTimeout(()=>{
  m.classList.remove('pgOut');
  m.style.setProperty('--ox',ox+'%');
  m.style.setProperty('--oy',oy+'%');
  m.querySelectorAll('.js-plotly-plot').forEach(d=>delete d.dataset.drawn);
  fn();
  [...m.children].forEach((c,i)=>c.style.setProperty('--i',Math.min(i,9)));
  void m.offsetWidth;                              // restart the animation
  m.classList.add('pgIn');
  afterRender();
  setTimeout(()=>{m.classList.remove('pgIn');_pgBusy=false;
    try{[...m.querySelectorAll('.js-plotly-plot')].forEach(p=>Plotly.Plots.resize(p));}catch(e){}
  },640);
 },170);
}
function afterRender(){
 const m=document.getElementById('main');
 for(const k in _GROWN)delete _GROWN[k];   // each page visit animates once; slider moves do not
 animateCounters(m);
 armReveal(m);
}
