/* Charts fade up as they finish drawing, and bar charts grow from the baseline the first time
   they scroll into view. The CSS for the fade has been in the stylesheet since the first build and
   nothing ever added the class; the growth is new. Both are visual only. The numbers recorded for
   the Table and CSV buttons are always the real ones, because the record is written from the data
   handed to the wrapper, before anything is zeroed. */
const _GROWN={};                       // chart ids already animated on this page visit
let _growObs=null;
function isBarish(d){return Array.isArray(d)&&d.some(t=>t&&t.type==='bar');}
/* Draw the bars flat, then run them up to their real height the moment the chart is on screen.
   Vertical bars grow on y, horizontal ones on x. Only bar traces are touched, so a line drawn on
   the same axes stays where it is and the bars rise past it. */
function armGrow(div,data,layout,cfg){
 if(reduceMo())return false;
 const id=div&&div.id; if(!id||_GROWN[id])return false;
 if(!isBarish(data))return false;
 const idx=[],zeros=[],reals=[]; let horiz=null;
 for(let i=0;i<data.length;i++){
  const t=data[i]; if(!t||t.type!=='bar')continue;
  const hz=(t.orientation==='h'), k=hz?'x':'y';
  if(!Array.isArray(t[k])||!t[k].length)continue;
  if(horiz===null)horiz=hz; else if(horiz!==hz)return false;   // mixed orientation, leave it alone
  idx.push(i); reals.push(t[k]); zeros.push(t[k].map(()=>0));
 }
 if(!idx.length)return false;
 const key=horiz?'x':'y';
 _GROWN[id]=1;
 try{ Plotly.restyle(div,{[key]:zeros},idx); }catch(e){ return false; }
 div._growRun=function(){
  try{ Plotly.animate(div,{data:reals.map(v=>({[key]:v})),traces:idx},
        {transition:{duration:820,easing:'cubic-out'},frame:{duration:820,redraw:false}});
       // redraw:false keeps the frame cheap but leaves the axis range computed while the bars were
       // flat, which on an autoranged chart collapses it. Restore the range once the run finishes.
       setTimeout(()=>{try{
         const ax=(key==='x')?'xaxis':'yaxis';
         const lay=(div.layout||{})[ax]||{};
         if(lay.range==null||lay.autorange!==false)Plotly.relayout(div,{[ax+'.autorange']:true});
       }catch(e){}},880);
  }
  catch(e){ try{ Plotly.restyle(div,{[key]:reals},idx); }catch(e2){} }
 };
 if(!_growObs)_growObs=new IntersectionObserver(es=>{
   es.forEach(x=>{if(x.isIntersecting){_growObs.unobserve(x.target);
     const f=x.target._growRun; if(f&&!x.target._grown){x.target._grown=1;setTimeout(f,60);}}});
 },{rootMargin:'0px 0px -4% 0px',threshold:0.1});
 const r=div.getBoundingClientRect();
 if(r.top<innerHeight*0.96&&r.bottom>0){div._grown=1;setTimeout(div._growRun,110);}   // already in view
 else _growObs.observe(div);
 // Safety net. A chart that never intersects, because it sits in a collapsed container or the
 // reader simply never scrolls to it, must not be left sitting at zero. Release it regardless
 // after a few seconds; if it is off screen nobody sees the jump, and if it is on screen the
 // observer will already have run it.
 setTimeout(()=>{const f=div._growRun; if(f&&!div._grown){div._grown=1;try{_growObs.unobserve(div);}catch(e){} f();}},6000);
 return true;
}
/* ---------- universal chart numbers: table view + downloads for every chart ----------
   Plotly.react is wrapped so each chart's plotted series are recorded as drawn.
   The Table, TXT, CSV and Copy controls under a chart run off that record, so the
   numbers shown and exported are exactly the numbers plotted. Excluded: the map,
   and the BE production views that carry their own richer table pipeline. */
const CT={};
function ctSkipId(id){
 if(id==='c_map'||id==='pshape2'||id==='pcdf'||id==='pcorr2'||id==='px_chart')return true;
 if(id==='pd_sub'||id==='ab_sub'||id==='ng_sub'||id==='ab_third')return true;           // map; BE charts with their own richer tables
 if(id==='pmain')return active==='profiles'&&profView!=='mix';       // BE views keep their own pipeline; grid mix and SPV supply get the toolbar
 return false;
}
function ctInstall(){
 if(!window.Plotly||Plotly.__ct)return;
 const orig=Plotly.react.bind(Plotly);
 Plotly.__ct=true;
 Plotly.react=function(el,data,layout,cfg){
  const id=typeof el==='string'?el:(el&&el.id);
  // The record behind Table and CSV must be immune to the bar-growth animation, which replaces a
  // trace's y array with zeros until the chart is on screen. Only bar charts are ever touched, so
  // only bar charts pay for the copy.
  try{if(id){
   const barish=(data||[]).some(t=>t&&t.type==='bar');
   CT[id]={data:barish?(data||[]).map(t=>{const c=Object.assign({},t);
     if(Array.isArray(t.x))c.x=t.x.slice(); if(Array.isArray(t.y))c.y=t.y.slice(); return c;}):(data||[])};
   setTimeout(()=>ctEnsure(id),0);}}catch(e){}
  const r=orig(el,data,layout,cfg);
  // first paint of this div in this page view: let it draw itself in
  try{
   if(!reduceMo()){
    const d=(typeof el==='string')?document.getElementById(el):el;
    if(d&&!d.dataset.drawn){
     d.dataset.drawn='1';
     const isMap=(data||[]).some(t=>t&&/map/i.test(t.type||''));
     const cls=isMap?'mapIn':'drawIn';
     d.classList.remove('drawIn','mapIn'); void d.offsetWidth; d.classList.add(cls);
     setTimeout(()=>d.classList.remove(cls),1250);
     try{armGrow(d,data,layout,cfg);}catch(e){}
    }
   }
  }catch(e){}
  return r;
 };
}
(function ctPoll(){window.Plotly?ctInstall():setTimeout(ctPoll,80);})();
function ctEnsure(id){
 if(ctSkipId(id))return;
 const div=document.getElementById(id); if(!div||document.getElementById('ct_'+id))return;
 const bar=document.createElement('div');
 bar.id='ct_'+id; bar.className='ctBar';
 bar.innerHTML=`<button class="chip" style="cursor:pointer" onclick="ctToggle('${id}')">Table</button>
  <button class="chip" style="cursor:pointer" onclick="ctDl('${id}','csv')">CSV</button>`;
 // float the bar over the top-right of the chart instead of pushing it down the page
 let wrap=div.parentElement;
 if(!wrap||!wrap.classList.contains('chartWrap')){
  wrap=document.createElement('div'); wrap.className='chartWrap';
  div.parentElement.insertBefore(wrap,div); wrap.appendChild(div);
 }
 wrap.appendChild(bar);
 const panel=document.createElement('div'); panel.id='ctp_'+id; panel.className='ctPanel'; panel.style.display='none';
 wrap.insertAdjacentElement('afterend',panel);
}
function ctMatrix(id){
 const rec=CT[id]; if(!rec)return null;
 const D=rec.data;
 if(D.length&&D[0].z){                                   // heatmap or surface: matrix
  const t=D[0], xs=t.x||t.z[0].map((_,i)=>i);
  return {cols:['row \\ col'].concat(xs.map(String)),
          rows:t.z.map((r,ri)=>[(t.y&&t.y[ri]!=null?t.y[ri]:ri)].concat(r))};
 }
 if(D.length&&D[0].labels)                               // pie
  return {cols:['label','value'],rows:D[0].labels.map((l,i)=>[l,D[0].values[i]])};
 const xs=[], seen=new Set();                            // xy series: union of x
 D.forEach(t=>(t.x||[]).forEach(x=>{const k=String(x);if(!seen.has(k)){seen.add(k);xs.push(x);}}));
 const maps=D.map(t=>{const m=new Map();(t.x||[]).forEach((x,i)=>m.set(String(x),t.y?t.y[i]:''));return m;});
 return {cols:['x'].concat(D.map((t,i)=>t.name||('series '+(i+1)))),
         rows:xs.map(x=>[x].concat(maps.map(m=>{const v=m.get(String(x));return v===undefined?'':v;})))};
}
function ctText(id,sep){
 const m=ctMatrix(id); if(!m)return'';
 return [m.cols.join(sep)].concat(m.rows.map(r=>r.map(v=>sep===','&&String(v).includes(',')?'"'+v+'"':v).join(sep))).join('\r\n');
}
function ctDl(id,fmt){
 const t=ctText(id,fmt==='csv'?',':'\t'); if(!t)return;
 const b=new Blob([t],{type:'text/plain;charset=utf-8'});
 const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='burgenland_'+id+'.'+fmt;a.click();
 setTimeout(()=>URL.revokeObjectURL(a.href),4000);
}
function ctToggle(id){
 const p=document.getElementById('ctp_'+id); if(!p)return;
 if(p.style.display==='none'){
  const m=ctMatrix(id); if(!m)return;
  p.innerHTML='<div style="max-height:420px;overflow:auto;border:1px solid var(--line);border-radius:8px"><table style="width:100%;border-collapse:collapse;font-size:12.5px;font-variant-numeric:tabular-nums"><thead style="position:sticky;top:0;background:#16202c"><tr>'+
   m.cols.map(c=>'<th style="text-align:left;padding:4px 9px">'+c+'</th>').join('')+
   '</tr></thead><tbody>'+
   m.rows.map(r=>'<tr>'+r.map(v=>'<td style="padding:2px 9px;border-top:1px solid var(--gridfaint);text-align:'+(typeof v==='number'?'right':'left')+'">'+v+'</td>').join('')+'</tr>').join('')+
   '</tbody></table></div>';
  p.style.display='block';
 }else{p.style.display='none';p.innerHTML='';}
}

/* ---------- raw 15-minute data explorer (Production > Raw data) ----------
   The full series ships only as bedata_enc.bin: gzip then AES-256-GCM, key derived
   from the access code with PBKDF2 (SHA-256, 310k rounds). Decrypted in the browser,
   held in memory only. Table, downloads and copy all run through rxRowVals, so every
   number shown is the number exported. */
let RAWX=null, rxSel=[], rxIdx=new Uint32Array(0), rxGrid='', rxDeb=null, rxT0=null, rxF={};
const RXH=24, RXMN=["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"],
      RXDW=["Mon","Tue","Wed","Thu","Fri","Sat","Sun"], rxPad=x=>String(x).padStart(2,'0');
async function rxDerive(pw){
 const km=await crypto.subtle.importKey('raw',new TextEncoder().encode(pw),'PBKDF2',false,['deriveKey']);
 return crypto.subtle.deriveKey({name:'PBKDF2',salt:new TextEncoder().encode('gdc-nickelsdorf::raw'),iterations:310000,hash:'SHA-256'},km,{name:'AES-GCM',length:256},true,['decrypt']);
}
async function rxStoreKey(pw){
 const k=await rxDerive(pw);
 const raw=await crypto.subtle.exportKey('raw',k);
 try{sessionStorage.setItem('gdcK',btoa(String.fromCharCode(...new Uint8Array(raw))));}catch(e){}
}
async function rxKey(){
 const b64=sessionStorage.getItem('gdcK'); if(!b64)return null;
 const bytes=Uint8Array.from(atob(b64),c=>c.charCodeAt(0));
 return crypto.subtle.importKey('raw',bytes,{name:'AES-GCM'},false,['decrypt']);
}
function rxStatus(html){const e=document.getElementById('rxStatus');if(e)e.innerHTML=html;}
function rxPage(){
 return `<div class="panel">
  <div id="rxStatus" class="muted" style="min-height:18px">Preparing…</div>
  <div id="rxKeyRow" style="display:none;margin-top:8px"><div class="rxRow" style="margin:0">
    <label class="rxF">Access code<input type="password" id="rxPw" style="width:190px" onkeydown="if(event.key==='Enter')rxInlineTry()"></label>
    <button class="chip" style="cursor:pointer" onclick="rxInlineTry()">Load raw data</button></div></div>
  <div id="rxBody" style="display:none;margin-top:12px">
   <div class="rxq" id="rxQual" style="${rxScope?'display:none':''}"></div>
   <div class="rxChk" id="rxPlantChk" style="${rxScope?'display:none':''}"></div>
   <div class="rxRow" style="${rxScope?'display:none':''}">
    <label class="rxF">From<input type="date" id="rxFrom"></label>
    <label class="rxF">To<input type="date" id="rxTo"></label>
    <label class="rxF">Year<select id="rxYear"><option value="">all</option></select></label>
    <label class="rxF">Month<select id="rxMonth"><option value="">all</option></select></label>
    <label class="rxF">Day<select id="rxDay"><option value="">all</option></select></label>
    <label class="rxF">Hour<select id="rxHour"><option value="">all</option></select></label>
    <label class="rxF">Min total kWh<input type="number" id="rxMin" style="width:96px" placeholder="-"></label>
    <label class="rxF">Max total kWh<input type="number" id="rxMax" style="width:96px" placeholder="-"></label>
    <label class="rxF" style="flex-direction:row;align-items:center;gap:6px;padding-bottom:6px"><input type="checkbox" id="rxMiss">missing only</label>
    <button class="chip" style="cursor:pointer" onclick="rxClearF()">Clear filters</button>
    <span class="rxCnt">showing <b id="rxNShow">0</b> of <b id="rxNTot">0</b> intervals</span>
   </div>
   <div class="rxRow">
    <button class="chip" style="cursor:pointer;border-color:var(--acc)" onclick="rxDl('txt',true)">TXT · current view</button>
    <button class="chip" style="cursor:pointer" onclick="rxDl('csv',true)">CSV · current view</button>
    <button class="chip" style="cursor:pointer" onclick="rxDl('txt',false)">TXT · full dataset</button>
    <button class="chip" style="cursor:pointer" onclick="rxDl('csv',false)">CSV · full dataset</button>
    <button class="chip" style="cursor:pointer" onclick="rxCopy()">Copy filtered rows</button>
   </div>
   <div id="rxWrap"><div id="rxHdr"></div><div id="rxVp"><div id="rxSp"></div></div></div>
   <div class="muted" style="margin-top:8px">One row per 15-minute interval; values are kWh per interval, full precision, exactly as received. Timestamp marks the interval end, local Austrian time. Blank cells: no record for that plant. Filtered downloads reflect the filters above; full files ignore them. Decrypted data stays in this browser tab.</div>
  </div></div>`;
}
function rxBoot(){
 if(RAWX){rxStatus('Loaded: <b>'+RAWX.n.toLocaleString('en-US')+'</b> 15-minute intervals per plant, '+RAWX.plants.map(p=>p.label).join(' · ')+'.');rxShow();return;}
 if(!window.crypto||!crypto.subtle){rxStatus('This browser blocks WebCrypto. Open the page over https.');return;}
 if(!sessionStorage.getItem('gdcK')){
  rxStatus('The raw series is published only as encrypted data. Enter the access code once to decrypt it here.');
  const kr=document.getElementById('rxKeyRow');if(kr)kr.style.display='block';
  return;
 }
 rxLoad();
}
async function rxInlineTry(){
 const el=document.getElementById('rxPw'); const v=(el&&el.value)||'';
 if(!v){if(el)el.focus();return;}
 let hex='';
 try{
  const buf=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(GATE.salt+v));
  hex=[...new Uint8Array(buf)].map(b=>b.toString(16).padStart(2,'0')).join('');
 }catch(e){rxStatus('This browser blocked the check. Open the page over https.');return;}
 if(hex!==GATE.h){rxStatus('Not recognised.');el.select();return;}
 rxStatus('Deriving key…');
 await rxStoreKey(v);
 GATE.open=true; try{sessionStorage.setItem('gdcGate','1');}catch(e){}
 const kr=document.getElementById('rxKeyRow');if(kr)kr.style.display='none';
 rxLoad();
}
async function rxLoad(){
 try{
  rxStatus('Downloading encrypted data (0.9 MB)…');
  const rs=await fetch('bedata_enc.bin');
  if(!rs.ok)throw new Error('fetch '+rs.status);
  const blob=new Uint8Array(await rs.arrayBuffer());
  if(blob.length<21||String.fromCharCode(...blob.slice(0,4))!=='GDC1')throw new Error('bad header');
  rxStatus('Decrypting…');
  const key=await rxKey();
  if(!key){rxBoot();return;}
  let pt;
  try{pt=await crypto.subtle.decrypt({name:'AES-GCM',iv:blob.slice(4,16)},key,blob.slice(16));}
  catch(e){
   try{sessionStorage.removeItem('gdcK');}catch(_){ }
   rxStatus('The stored key does not open this file. Enter the access code again.');
   const kr=document.getElementById('rxKeyRow');if(kr)kr.style.display='block';
   return;
  }
  if(typeof DecompressionStream==='undefined'){rxStatus('This browser cannot decompress the data stream. Use a current Chrome, Edge, Firefox or Safari.');return;}
  rxStatus('Decompressing…');
  const ds=new Response(new Blob([pt]).stream().pipeThrough(new DecompressionStream('gzip')));
  RAWX=JSON.parse(await ds.text());
  rxT0=new Date(RAWX.t0.replace(' ','T'));
  rxSel=RAWX.plants.map(p=>p.key);
  rxBoot();
 }catch(e){
  rxStatus(location.protocol==='file:'
   ? 'The encrypted file cannot be fetched from a local file:// page. Use the live page, or the offline explorer in 02 Data room.'
   : 'Could not load bedata_enc.bin ('+(e&&e.message||e)+'). Check that deploy.bat pushed it.');
 }
}
function rxTAt(i){return new Date(rxT0.getTime()+i*900000);}
function rxCols(){
 const base=["datetime","date","year","month","month_name","day","day_of_week","hour","minute","time"];
 const pc=RAWX.plants.filter(p=>rxSel.includes(p.key)).map(p=>p.safe+"_kWh");
 return base.concat(pc,["total_production_kWh","plants_reporting"]);
}
function rxRowVals(i,round){
 const d=rxTAt(i);
 const base=[`${d.getFullYear()}-${rxPad(d.getMonth()+1)}-${rxPad(d.getDate())} ${rxPad(d.getHours())}:${rxPad(d.getMinutes())}`,
  `${d.getFullYear()}-${rxPad(d.getMonth()+1)}-${rxPad(d.getDate())}`,d.getFullYear(),d.getMonth()+1,RXMN[d.getMonth()],
  d.getDate(),RXDW[(d.getDay()+6)%7],d.getHours(),d.getMinutes(),`${rxPad(d.getHours())}:${rxPad(d.getMinutes())}`];
 let tot=0,nrep=0;
 const pv=[];
 for(const p of RAWX.plants){const v=RAWX.data[p.key][i];
   if(rxSel.includes(p.key))pv.push(v==null?"":(round?Math.round(v):v));
   if(v!=null){tot+=v;nrep++;}}
 return base.concat(pv,[nrep?(round?Math.round(tot):+tot.toFixed(4)):"",nrep]);
}
function rxPasses(i){
 const d=rxTAt(i), F=rxF;
 if(F.from&&d<F.from)return false;
 if(F.to&&d>F.to)return false;
 if(F.year&&d.getFullYear()!==F.year)return false;
 if(F.month&&d.getMonth()+1!==F.month)return false;
 if(F.day&&d.getDate()!==F.day)return false;
 if(F.hour!==null&&d.getHours()!==F.hour)return false;
 let tot=0,has=false,missing=false,anySel=false;
 for(const p of RAWX.plants){const v=RAWX.data[p.key][i];
  if(rxSel.includes(p.key)){anySel=true;if(v==null)missing=true;else{has=true;tot+=v;}}}
 if(!anySel)return false;
 if(!has&&!missing)return false;
 if(F.miss&&!missing)return false;
 if(F.min!=null&&tot<F.min)return false;
 if(F.max!=null&&tot>F.max)return false;
 return has||missing;
}
function rxReadF(){
 const g=id=>{const e=document.getElementById(id);return e?e.value:''};
 rxF={from:g('rxFrom')?new Date(g('rxFrom')+"T00:00:00"):null,
  to:g('rxTo')?new Date(g('rxTo')+"T23:59:59"):null,
  year:g('rxYear')?+g('rxYear'):null,month:g('rxMonth')?+g('rxMonth'):null,
  day:g('rxDay')?+g('rxDay'):null,hour:g('rxHour')===""?null:+g('rxHour'),
  min:g('rxMin')===""?null:+g('rxMin'),max:g('rxMax')===""?null:+g('rxMax'),
  miss:!!(document.getElementById('rxMiss')&&document.getElementById('rxMiss').checked)};
}
function rxRefilter(){clearTimeout(rxDeb);rxDeb=setTimeout(()=>{
 rxReadF();
 const a=[];for(let i=0;i<RAWX.n;i++)if(rxPasses(i))a.push(i);
 rxIdx=Uint32Array.from(a);
 const ns=document.getElementById('rxNShow');if(ns)ns.textContent=rxIdx.length.toLocaleString('en-US');
 rxHeader();rxLayout();
},180);}
function rxClearF(){['rxFrom','rxTo','rxYear','rxMonth','rxDay','rxHour','rxMin','rxMax'].forEach(id=>{const e=document.getElementById(id);if(e)e.value='';});
 const m=document.getElementById('rxMiss');if(m)m.checked=false;rxRefilter();}
function rxHeader(){
 const c=rxCols();
 rxGrid=c.map(x=>x==='datetime'?'150px':(x.endsWith('_kWh')?'128px':(x==='month_name'||x==='day_of_week'?'64px':'56px'))).join(' ');
 const h=document.getElementById('rxHdr');if(!h)return;
 h.style.gridTemplateColumns=rxGrid;
 h.innerHTML=c.map(x=>`<div title="${x}">${x}</div>`).join('');
 document.getElementById('rxSp').style.height=(rxIdx.length*RXH)+"px";
}
function rxLayout(){
 const vp=document.getElementById('rxVp'),sp=document.getElementById('rxSp');
 if(!vp||!sp)return;
 const s=vp.scrollTop,h=vp.clientHeight;
 const a=Math.max(0,Math.floor(s/RXH)-8),b=Math.min(rxIdx.length,Math.ceil((s+h)/RXH)+8);
 let html="";
 for(let r=a;r<b;r++){
  const vals=rxRowVals(rxIdx[r],true);
  html+=`<div class="rxr" style="top:${r*RXH}px;grid-template-columns:${rxGrid}">`+
   vals.map((v,ci)=>{const num=ci>=10;const miss=num&&v===""&&ci<vals.length-2;
     return `<div class="${num?'num':''}${miss?' miss':''}">${v===""&&num&&ci<vals.length-2?"·":v}</div>`;}).join('')+`</div>`;
 }
 sp.innerHTML=html;
}
function rxText(useFilter,sepr){
 const c=rxCols(); const out=[c.join(sepr)];
 const n=useFilter?rxIdx.length:RAWX.n;
 for(let r=0;r<n;r++){const i=useFilter?rxIdx[r]:r;
  out.push(rxRowVals(i).map(v=>sepr===','&&String(v).includes(',')?'"'+v+'"':v).join(sepr));}
 return out.join("\r\n");
}
function rxDl(fmt,useFilter){
 const sepr=fmt==='csv'?',':'\t';
 const txt=rxText(useFilter,sepr);
 const name=useFilter?`BE_raw_15min_production_filtered.${fmt}`:`BE_raw_15min_production_all_plants.${fmt}`;
 const b=new Blob([txt],{type:'text/plain;charset=utf-8'});
 const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();
 setTimeout(()=>URL.revokeObjectURL(a.href),4000);
}
function rxCopy(){
 const txt=rxText(true,'\t');
 const done=()=>rxStatus('Copied <b>'+rxIdx.length.toLocaleString('en-US')+'</b> rows to the clipboard.');
 if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(txt).then(done,done);
 else{const ta=document.createElement('textarea');ta.value=txt;document.body.appendChild(ta);ta.select();
  try{document.execCommand('copy');}catch(e){}document.body.removeChild(ta);done();}
}
function rxShow(){
 if(rxScope&&RAWX)rxSel=RAWX.plants.filter(p=>rxScope==='wind'?/wind/i.test(p.label):/pv|solar/i.test(p.label)).map(p=>p.key);
 const body=document.getElementById('rxBody');if(!body)return;
 body.style.display='block';
 const pc=document.getElementById('rxPlantChk');
 pc.innerHTML=RAWX.plants.map(p=>`<label><input type="checkbox" ${rxSel.includes(p.key)?'checked':''} data-k="${p.key}">${p.label} · ${p.mw} MW</label>`).join('');
 pc.querySelectorAll('input').forEach(cb=>cb.addEventListener('change',()=>{
  rxSel=[...pc.querySelectorAll('input:checked')].map(x=>x.dataset.k);rxRefilter();}));
 const fy=document.getElementById('rxYear');if(fy.options.length===1)[2023,2024,2025,2026].forEach(y=>fy.add(new Option(y,y)));
 const fm=document.getElementById('rxMonth');if(fm.options.length===1)RXMN.forEach((m,i)=>fm.add(new Option(m,i+1)));
 const fd=document.getElementById('rxDay');if(fd.options.length===1)for(let d=1;d<=31;d++)fd.add(new Option(d,d));
 const fh=document.getElementById('rxHour');if(fh.options.length===1)for(let h=0;h<24;h++)fh.add(new Option(rxPad(h)+":xx",h));
 ['rxFrom','rxTo','rxYear','rxMonth','rxDay','rxHour','rxMin','rxMax','rxMiss'].forEach(id=>{
  const e=document.getElementById(id);if(e)e.addEventListener('input',rxRefilter);});
 document.getElementById('rxVp').addEventListener('scroll',rxLayout);
 document.getElementById('rxNTot').textContent=RAWX.n.toLocaleString('en-US');
 const q=document.getElementById('rxQual');
 q.innerHTML=RAWX.plants.map(p=>{const Q=RAWX.quality[p.key];
  return `<div class="rxqc"><b>${Q.label}</b><table>
  <tr><td>window</td><td>${Q.windowFrom} to ${Q.windowTo}</td></tr>
  <tr><td>recorded / expected</td><td>${Q.recorded.toLocaleString('en-US')} / ${Q.expected.toLocaleString('en-US')}</td></tr>
  <tr><td>missing</td><td>${Q.missing.toLocaleString('en-US')} (${Q.missingDST} DST spring hour)</td></tr>
  <tr><td>duplicates · negatives</td><td>${Q.duplicates} · ${Q.negatives}</td></tr>
  <tr><td>peak, % of rating</td><td>${Q.peakPctRated}%</td></tr></table></div>`;}).join('');
 rxRefilter();
}


/* ============ 16 · MOTION UPGRADES ============
   Presentation only: counters that ease between slider positions, a cursor-lit
   sheen on cards, a springy thumb under segmented controls, magnetic hover on
   buttons, a scroll rail with one dot per section, and the pinned overview
   story. Everything degrades to the static page under prefers-reduced-motion,
   and no model number is produced or altered here. */

let _pgNav=true;                    /* true while a render came from navigation, not a control */
const _CPREV={};                    /* last value shown per counter key */
const CT_SEL2='.kpi .v, .kpi .mv2, .figRow .n, .evCard .figure, .heroStrip .v';

function _ctParse(el){
 const html=el.innerHTML, m=html.match(/(-?\d[\d,]*\.?\d*)/);
 if(!m)return null;
 const raw=m[1], target=parseFloat(raw.replace(/,/g,''));
 if(!isFinite(target)||Math.abs(target)>1e9)return null;
 return {html:html,raw:raw,target:target,dec:(raw.split('.')[1]||'').length};
}
function _ctKey(el,i){
 const k=el.closest('.kpi'), lab=k?((k.querySelector('.l')||{}).textContent||''):'';
 return active+'|'+el.className+'|'+lab.trim()+'|'+i;
}
function seedCounters(root){
 root.querySelectorAll(CT_SEL2).forEach((el,i)=>{const p=_ctParse(el);if(p)_CPREV[_ctKey(el,i)]=p.target;});
}
function animateDeltas(root){
 root.querySelectorAll(CT_SEL2).forEach((el,i)=>{
  const p=_ctParse(el); if(!p)return;
  const key=_ctKey(el,i), old=_CPREV[key]; _CPREV[key]=p.target;
  if(old==null||old===p.target||reduceMo())return;
  el.dataset.ctd='1';
  const t0=performance.now(), dur=340;
  const tick=now=>{
   if(!el.isConnected)return;
   const q=Math.min(1,(now-t0)/dur), e2=1-Math.pow(1-q,3);
   const v=old+(p.target-old)*e2;
   el.innerHTML=q<1
     ?p.html.replace(p.raw,v.toLocaleString('en-US',{minimumFractionDigits:p.dec,maximumFractionDigits:p.dec}))
     :p.html;
   if(q<1)requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
 });
}

/* ---- springy segmented controls: one sliding thumb per .seg ---- */
const _SEGO={};
function _segKey(seg){const all=[...document.querySelectorAll('.seg')];return active+'#'+all.indexOf(seg);}
document.addEventListener('pointerdown',e=>{
 const b=e.target&&e.target.closest?e.target.closest('.seg button'):null; if(!b)return;
 const seg=b.closest('.seg'), on=seg&&seg.querySelector('button.on'); if(!on)return;
 _SEGO[_segKey(seg)]={l:on.offsetLeft,t:on.offsetTop,w:on.offsetWidth,h:on.offsetHeight};
},true);
function segArm(root){
 (root||document).querySelectorAll('.seg').forEach(seg=>{
  const on=seg.querySelector('button.on');
  let th=seg.querySelector(':scope>.segTh');
  if(!on||!on.offsetWidth){if(th)th.remove();seg.classList.remove('thmd');return;}
  if(!th){th=document.createElement('span');th.className='segTh';seg.prepend(th);}
  seg.classList.add('thmd');
  const key=_segKey(seg), old=_SEGO[key]; delete _SEGO[key];
  const put=(r,inst)=>{
   if(inst)th.style.transition='none';
   th.style.left=r.l+'px'; th.style.top=r.t+'px'; th.style.width=r.w+'px'; th.style.height=r.h+'px';
   if(inst){void th.offsetWidth; th.style.transition='';}
  };
  const now={l:on.offsetLeft,t:on.offsetTop,w:on.offsetWidth,h:on.offsetHeight};
  if(old&&!reduceMo()&&(old.l!==now.l||old.w!==now.w)){put(old,true);requestAnimationFrame(()=>put(now,false));}
  else put(now,true);
 });
}

/* ---- cursor-following sheen + magnetic buttons: one shared, throttled pointermove ---- */
const GLOW_SEL='.panel,.evCard,.navCard,.ovCard,.castCard,.kpi';
const MAG_SEL='.chip,.evCard .go,.splashBtn,#nav button';
let _glEl=null,_magEl=null,_pmQ=false,_pmE=null;
function _magRelease(el){el.classList.remove('magT');el.classList.add('magR');el.style.transform='';setTimeout(()=>el.classList.remove('magR'),560);}
document.addEventListener('pointermove',e=>{
 if(e.pointerType&&e.pointerType!=='mouse')return;
 _pmE=e;
 if(_pmQ)return; _pmQ=true;
 requestAnimationFrame(()=>{
  _pmQ=false; const ev=_pmE; if(!ev)return;
  const rm=reduceMo();
  const tgt=ev.target&&ev.target.closest?ev.target:null;
  const g=tgt?tgt.closest(GLOW_SEL):null;
  if(_glEl&&_glEl!==g){_glEl.classList.remove('glOn');_glEl=null;}
  if(g&&!rm){
   _glEl=g;
   let sh=g.querySelector(':scope>.glShine');
   if(!sh){sh=document.createElement('div');sh.className='glShine';g.prepend(sh);}
   const r=g.getBoundingClientRect();
   g.style.setProperty('--gx',((ev.clientX-r.left)/Math.max(1,r.width)*100).toFixed(1)+'%');
   g.style.setProperty('--gy',((ev.clientY-r.top)/Math.max(1,r.height)*100).toFixed(1)+'%');
   g.classList.add('glOn');
  }
  const t=tgt?tgt.closest(MAG_SEL):null;
  if(_magEl&&_magEl!==t){_magRelease(_magEl);_magEl=null;}
  if(t&&!rm){
   _magEl=t;
   const r=t.getBoundingClientRect();
   const dx=(ev.clientX-(r.left+r.width/2))/Math.max(1,r.width);
   const dy=(ev.clientY-(r.top+r.height/2))/Math.max(1,r.height);
   t.classList.add('magT'); t.classList.remove('magR');
   t.style.transform='translate('+(dx*7).toFixed(1)+'px,'+(dy*4.5).toFixed(1)+'px)';
  }
 });
},{passive:true});
document.addEventListener('pointerout',e=>{
 if(e.relatedTarget)return;
 if(_magEl){_magRelease(_magEl);_magEl=null;}
 if(_glEl){_glEl.classList.remove('glOn');_glEl=null;}
});
document.addEventListener('pointerdown',()=>{if(_magEl)_magEl.style.transform='';},true);

/* ---- scroll rail: one dot per section kicker ---- */
let _railA=[],_fxRz=null;
function buildRail(){
 const m=document.getElementById('main');
 let rail=document.getElementById('pgRail');
 const ks=m?[...m.querySelectorAll('.kick')].filter(k=>(k.textContent||'').trim()&&k.offsetParent!==null):[];
 const need=ks.length>=3&&document.documentElement.scrollHeight>innerHeight*2.05
   &&!document.body.classList.contains('printing')&&innerWidth>1200;
 if(!need){if(rail)rail.remove();_railA=[];return;}
 _railA=ks.map(k=>({el:k.closest('section,.sect,.pgHead,.panel')||k,label:(k.textContent||'').trim()}));
 if(!rail){rail=document.createElement('div');rail.id='pgRail';document.body.appendChild(rail);}
 rail.innerHTML='<div class="rTrack"><i class="rFill"></i></div>'+
  _railA.map((a,i)=>'<button class="rDot" data-i="'+i+'" aria-label="'+a.label.replace(/"/g,'&quot;')+'"><span>'+a.label+'</span></button>').join('');
 rail.querySelectorAll('.rDot').forEach(d=>d.addEventListener('click',()=>{
  const a=_railA[+d.dataset.i]; if(a&&a.el)a.el.scrollIntoView({behavior:reduceMo()?'auto':'smooth',block:'start'});
 }));
 railUpd();
}
function railUpd(){
 const rail=document.getElementById('pgRail'); if(!rail||!_railA.length)return;
 const vh=innerHeight, dh=document.documentElement.scrollHeight;
 const p=Math.max(0,Math.min(1,scrollY/Math.max(1,dh-vh)));
 const f=rail.querySelector('.rFill'); if(f)f.style.height=(p*100).toFixed(1)+'%';
 let act=0;
 _railA.forEach((a,i)=>{try{if(a.el.getBoundingClientRect().top<vh*0.45)act=i;}catch(e){}});
 [...rail.querySelectorAll('.rDot')].forEach((d,i)=>d.classList.toggle('on',i===act));
}

/* ---- the pinned overview story ---- */
function storySection(staticHTML){
 if(reduceMo()||innerWidth<1000||innerHeight<620||document.body.classList.contains('printing'))return staticHTML;
 const beats=[
  ['The parks',fmt(M.wind.mw,0)+' MW of wind and '+fmt(M.solar.mw,0)+' MWp of solar sell to the data center over private lines, not into the market.'],
  ['The line','A private 110 kV line, built, owned and financed by the Power SPV. PPA volumes carry no network charges.'],
  ['The load',fmt(M.dc.firmMW,0)+' MW firm, 8,760 hours a year. The battery rides through the gaps and the grid connection covers the balance.']];
 return '<section class="story"><div class="storyPin" data-step="0">'
  +'<div class="kick">How the power moves</div>'
  +'<h2 class="dsp">Generation behind the meter, the grid for balance.</h2>'
  +'<div class="flowWrap" style="margin-top:14px">'+flowDiagram()+'</div>'
  +'<div class="stBeats">'+beats.map((b,i)=>'<div class="stBeat'+(i===0?' on':'')+'"><div class="stNum">0'+(i+1)+'</div><b>'+b[0]+'</b><p>'+b[1]+'</p></div>').join('')+'</div>'
  +'</div></section>';
}
function storyUpd(){
 const st=document.querySelector('.story'); if(!st)return;
 const pin=st.querySelector('.storyPin'); if(!pin)return;
 const track=st.offsetHeight-pin.offsetHeight;
 const p=Math.max(0,Math.min(1,track>0?(66-st.getBoundingClientRect().top)/track:1));
 const step=p<0.34?0:(p<0.7?1:2);
 if(pin.dataset.step!==String(step)){
  pin.dataset.step=String(step);
  pin.querySelectorAll('.stBeat').forEach((b,i)=>b.classList.toggle('on',i===step));
 }
}

/* ---- shared post-render hook + scroll/resize plumbing ---- */
function postRender(){
 const m=document.getElementById('main'); if(!m)return;
 try{segArm(m);}catch(e){}
 try{if(_pgNav)seedCounters(m);else animateDeltas(m);}catch(e){}
 _pgNav=false;
 try{buildRail();}catch(e){}
 clearTimeout(postRender._t);
 postRender._t=setTimeout(()=>{try{buildRail();railUpd();}catch(e){}},1100);
 try{storyUpd();}catch(e){}
}
let _fxT=false;
addEventListener('scroll',()=>{if(_fxT)return;_fxT=true;requestAnimationFrame(()=>{_fxT=false;railUpd();storyUpd();});},{passive:true});
addEventListener('resize',()=>{clearTimeout(_fxRz);_fxRz=setTimeout(()=>{buildRail();railUpd();storyUpd();},220);});

setTheme(THEME,true);scenFromHash();buildNav();setTimeout(maybeSplash,60);render();afterRender();
if(typeof Plotly==='undefined'){(function w(){ (typeof Plotly!=='undefined') ? (render(),afterRender()) : setTimeout(w,100); })();}
